window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["pol"] = window.COMMON_BANK["pol"] || {name:"政治常识", items:[]};
window.COMMON_BANK["pol"].items.push(
{"id": "pol-1", "q": "延安时期，中国共产党逐步形成了一个“稳定的成熟的领导集体”，这个领导集体成员包括：", "options": ["毛泽东、朱德、刘少奇、周恩来、邓小平", "毛泽东、朱德、刘少奇、周恩来、任弼时", "毛泽东、朱德、刘少奇、周恩来、陈云", "毛泽东、朱德、刘少奇、周恩来、彭德怀"], "a": 1, "e": "B】本题考查政治常识。从1935年10月到1948年3月，是中国共产党历史上的延安时期。延安时期，中国共产党之所以能够从胜利走向更大的胜利，一个主要的原因是逐步形成了成熟的、稳定的以毛泽东为核心的领导集体。朱德、刘少奇、周恩来、任弼时等领导人也多是在革命战争中锻炼出来的领袖人物，都是国内、党内最优秀、最有才华的人物，具有崇高的革命理想和坚定的政治方向，对党和人民的事业无限忠诚，能够把马克思主义普遍真理和中国革命实际相结合，实事求是，具有丰富的实践经验和卓越的领导才能。A项错误，1956年中共八届一中全会上，邓小平当选为中央政治局常委、中央委员会总书记，成为以毛泽东为核心的第一代中央领导集体的重要成员，经过革命和建设的长期历练，也成为了第二代中央领导集体的核心，领导党和人民开创改革开放的新时期。B项正确，1945年4月23日至6月11日，中共七大胜利召开，选出了毛泽东、朱德、刘少奇、周恩来、任弼时为领导集体的新的书记处，宣告了以毛泽东为核心的中共第一代中央领导集体正式形成。C项错误，1950年10月27日，陈云被补选为中央书记处书记。而且在1956年中共八大上，毛泽东、刘少奇、周恩来、朱德、陈云、邓小平被选为政治局常委，其中毛泽东为中共中央主席，刘少奇、周恩来、朱德、陈云为副主席，邓小平为总书记。陈云、邓小平此时成为了中共第一代中央领导集体的重要成员。D项错误，彭德怀同志在延安时期，曾经担任过中共中央军委委员、八路军副总指挥，并于1940年在华北组织发动百团大战，于1943年回延安参加整风运动后，被任命为中央军委副主席兼总参谋长，他是国内和国际著名的军事家和政治故正确答案为B。", "tag": "政治常识"},
{"id": "pol-2", "q": "马克思主义中国化理论成果的精髓是：", "options": ["解放思想", "实事求是", "独立自主"], "a": 1, "e": "B】本题考查政治常识。马克思主义中国化就是将马克思主义的基本原理和中国革命与建设的实际情况相结合。这一概念由毛泽东在1938年中共六届六中全会上作《论新阶段》的报告时首次提出。毛泽东思想是马克思主义中国化第一次历史性飞跃的理论成果；中国特色社会主义理论体系，是马克思主义中国化第二次历史性飞跃的理论成果。毛泽东思想的精髓是实事求是；邓小平理论的精髓是解放思想、实事求是；“三个代表”重要思想的精髓是解放思想、实事求是、与时俱进；科学发展观的精髓是解放思想、实事求是、与时俱进、求真务实。因此“实事求是”贯穿了马克思主义中国化两大成果基本观点的始终。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-3", "q": "中国进入社会主义社会的主要标志是：", "options": ["中华人民共和国的成立", "过渡时期总路线的提出", "第一届全国人民代表大会的召开", "社会主义三大改造的完成"], "a": 3, "e": "D】本题考查毛泽东思想有关社会主义改造理论的知识。A项错误，1949年中华人民共和国的成立，标志着半殖民地半封建社会的结束，标志着中国新民主主义革命已经取得了基本的胜利，中国进入了新民主主义社会，并开始了新民主主义向社会主义转变的时期。B项错误，1952年底党中央按照毛泽东同志的建议，提出了党在过渡时期的总路线，指明了中国新民主主义过渡到社会主义的任务、途径和步骤，它的实质是改变生产关系，解决生产资料的所有制问题，为进一步解放和发展生产力、进入社会主义创造条件。C项错误，1954年9月15日，第一届全国人民代表大会第一次会议在北京召开，标志着我国以人民代表大会制度为根本的政治制度得到全面确立。D项正确，1956年底，随着农业、手工业和资本主义工商业社会主义改造的基本完成，我国实现了生产资料私有制向社会主义公有制的转变，标志着社会主义制度在中国的基本确立，中国已经从新民主主义社会进入社会主义社会。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-4", "q": "中国共产党自成立以来，就非常重视民族问题。1949 年《中国人民政治协商会议共同纲领》明确规定对少数民族地区实行民族区域自治制度。关于民族区域自治制度，下列说法不正确的是。", "options": ["民族区域自治制度是我国的基本政治制度之一，是一种新型的民主政治制度", "在国家的统一领导下，各少数民族聚居的地方实行区域自治，设立自治机关，行使自治权", "民族自治地方的人民代表大会有权依照当地民族的政治、经济、文化的特点，制定自治条例和单行条例", "我国现有的民族自治区，最早成立的是新疆维吾尔自治区"], "a": 3, "e": "D】A项正确，民族区域自治制度是我国的基本政治制度之一，是一种新型的民主政治制度，是建设中国特色社会主义政治的重要内容。B项正确，民族区域自治制度，是指在国家统一领导下，各少数民族聚居的地方实行区域自治，设立自治机关，行使自治权的制度。C项正确，民族自治地方的人民代表大会有权依照当地的政治、经济和文化的特点，制定自治条例和单行条例。自治条例规定有关本地方实行民族区域自治的基本问题；单行条例规定有关本地实行民族区域自治的某一方面的具体事项。D项错误，早在新中国成立以前，1947年5月1日，在党的领导下建立了我国第一个省级的内蒙古自治区，为以后在其他民族地区实行民族区域自治指明了方向，积累了宝贵的经验。新疆维吾尔自治区成立的时间是1955年10月1日，是第二个成立的自治区，与题意不符。本题为选非题，故正确答案为D。", "tag": "政治常识"},
{"id": "pol-5", "q": "习近平总书记指出，党对军队的绝对领导是我军的军魂和命根子，永远不能变，永远不能丢。党对军队绝对领导的根本原则和制度，发端于南昌起义，奠基于三湾改编，定型于。", "options": ["八七会议", "古田会议", "遵义会议", "毛儿盖会议"], "a": 1, "e": "B】本题主要考查政治常识。古田会议，是1929年12月28日至29日在福建省龙岩市上杭县古田召开的第九次党的代表大会，会议决议批判了主张军事领导政治，把军队凌驾于党的领导之上的错误思想，明确地规定了政治工作在军队中的地位和作用，阐明了坚持党对军队的绝对领导，是人民军队建设的根本原则。A项错误，八七会议，于1927年8月7日召开，会议批判和纠正了陈独秀右倾机会主义错误，确定了土地革命和武装斗争的总方针，决定发动秋收起义，毛泽东出席了这次会议，并提出了著名的“枪杆子里出政权”的论断。B项正确，党对军队的绝对领导的根本原则和制度完成于（定型于）古田会议。C项错误，遵义会议，于1935年1月召开，会议结束了王明“左”倾机会主义路线在党中央的统治，确立了以毛泽东为代表的新的中央正确领导。D项错误，毛儿盖会议，于1935年8月在四川毛儿盖召开，会议对张国焘的分裂路线进行了坚决斗争，挫败了分裂红军的企图。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-6", "q": "毛泽东全面论述社会主义基本矛盾问题的著作是：", "options": ["《实践论》", "《矛盾论》", "《论十大关系》", "《关于正确处理人民内部矛盾的问题》"], "a": 3, "e": "D】《关于正确处理人民内部矛盾的问题》是毛泽东论述中国社会主义革命和社会主义建设的重要著作。由1957年2月27日毛泽东在最高国务会议第十一次（扩大）会议上讲话修改和补充而成，同年6月19日在《人民日报》上发表。全文阐述了12个问题，贯穿全文的基本思想是：把正确区分和处理人民内部矛盾，作为社会主义国家政治生活的主要内容。《实践论》以实践观点为基础，以认识和实践的辩证统一为中心，系统地论述了能动的革命的反映论。《矛盾论》是以对立统一规律为核心，阐述矛盾普遍性和特殊性的相互关系，强调矛盾的特殊性，从方法论上批判了“左”“右倾”的错误思想，从理论与实践的结合上全面说明和发挥了唯物辩证法的实质和核心，对立统一规律。《论十大关系》总结了我国社会主义建设的经验，提出了调动一切积极因素为社会主义建设事业服务的基本方针，对适合中国情况的社会主义建设道路进行了初步的探索。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-7", "q": "上，这“四风”指的是：", "options": ["宣教经个", "教个享奢", "形官享奢", "经享个官"], "a": 2, "e": "C】动的主要任务聚焦到作风建设上，集中解决形式主义、官僚主义、享乐主义和奢靡之风这“四风”问题。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-9", "q": "我党的根本领导方法和工作方法是：", "options": ["独立自主，自力更生", "解放思想，实事求是"], "a": 1, "e": "B】C项错误，“独立自主，自力更生”是我国革命、建设和改革开放的基本经验和重要原则；D项错误，“解放思想，实事求是”是邓小平理论的精髓。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-11", "q": "下列哪次会议把毛泽东思想确立为党的指导思想：", "options": ["中共七大", "遵义会议", "中共八大", "瓦窑堡会议"], "a": 0, "e": "【A】中共七大于1945年4月23日至6月11日在延安举行。大会通过了毛泽东《论联合政府》的政治报告，并确立毛泽东思想为党的指导思想，将毛泽东思想写入党章。故正确答案为A。本题相关知识点：遵义会议是指1935年1月15日至17日，中共中央政治局在贵州遵义召开的独立自主地解决中国革命问题的一次极其重要的扩大会议。遵义会议事实上确定了毛泽东的领导地位。中共八大于1956年9月15日至27日在北京举行，大会通过了第二个五年计划的建议和新党章，确定把党的工作重点转向社会主义建设。瓦窑堡会议是中国共产党于1935年12月17日至25日在陕北瓦窑堡召开的政治局扩大会议。该会议批判了党内长期存在着的“左”倾关门主义，制定了抗日民族统一战线的策略方针。", "tag": "政治常识"},
{"id": "pol-12", "q": "近年来，我国置身世界大发展大变革大调整中，不惑于纷乱现象，不畏于艰难险阻，以元首外交引领扩大全球朋友圈、以开放合作之姿谋求各国共同发展、力倡多边主义推动全球治理改革，不断开创中国特色大国外交新局面。这表明，中国特色大国外交是。①以维护各国共同利益为目的，促进共同发展。②主导全球多边治理，建立国际政治经济新秩序。③坚持独立自主的和平外交政策，发挥负责任大国的作用。④坚持合作共赢，推动构建人类命运共同体。", "options": ["①②", "①③④", "②③④", "③④"], "a": 1, "e": "【B】本题考查政治常识。①③④正确，习近平同志在十九大报告中提出，坚持和平发展道路，推动构建人类命运共同体。中国将高举和平、发展、合作、共赢的旗帜，恪守维护世界和平、促进共同发展的外交政策宗旨，坚定不移在和平共处五项原则基础上发展同各国的友好合作，推动建设相互尊重、公平正义、合作共赢的新型国际关系。②错误，中国积极致力于全球多边治理，但不是“主导”，中国尊重各国人民自主选择发展道路的权利，维护国际公平正义，反对把自己的意志强加于人，反对干涉别国内政，反对以强凌弱。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-13", "q": "调结构、提品质、促融合是当前我国农业供给侧结构性改革的主要内容。下列措施符合这一改革要求的是", "options": ["调整渔业、林业和畜牧业的比重，确保农业占比稳步增长", "增加财政收入，确保粮食产品、进口量及库存量三量齐增", "提高主要粮食作物收购价，完善补贴制度，确保粮食安全", "降低单位耕地农药使用量，提高绿色农产品生产加工能力"], "a": 3, "e": "【D】本题考查政治常识。A项错误，第一产业包括农业、林业、牧业和渔业，因此A项调整的是第一产业的内部结构，而题干问的是农业的供给侧改革，主体不一致，因此A项错误。B项错误，增加财政收入属于政府的宏观调控经济手段，不是从农业自身层面作出的改变，因此不属于农业供给侧改革的内容。C项错误，国家提高农产品收购价格属于宏观调控经济手段，不属于农业供给侧改革的内容。D项正确，降低单位耕地农药使用量，提高绿色农产品加工生产能力，能够提高农产品品质，扩大有效供给，属于农业供给侧改革的内容。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-14", "q": "当今世界不稳定不确定因素明显增加，我们要坚持底线思维，居安思危、未雨绸缪，做好应付最坏局面的思想准备。下列表述体现了坚持底线思维的是", "options": ["政治建设方面绝不能犯颠覆性错误", "经济建设方面努力实现高质量发展", "文化建设方面要繁荣社会主义文艺", "外交战略方面构建人类命运共同体"], "a": 0, "e": "【A】本题考查政治常识。A项正确，政治安全攸关党和国家的安危，是维护国家安全的根本。如果在事关全局的政治问题上随波逐流，丧失原则和立场，就会严重危害党和人民事业的发展。因此政治建设决不能犯颠覆性错误，这是一种底线。BCD项错误，底线思维具有目的性、价值性，以实现和维护一定利益和价值为旨归。坚持和发展中国特色社会主义，全面建成社会主义现代化强国，实现中华民族伟大复兴的中国梦，是我们坚持底线思维的总体价值目标。这一总体价值目标，是通过经济、政治、文化、社会、生态文明各个方面建设来体现和实现的。BCD项不属于坚持底线思维，是为了实现总体价值目标在经济、文化、外交战略建设方面的表现。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-15", "q": "按照城市品质提升的总体要求，住建部于2019 年7 月在9 个城市开展规范城市户外广告设施管理工作。就政策执行来说，下列举措与此属于同一类的是", "options": ["甲省为鼓励高新技术产业发展出台优惠补贴政策", "乙省借鉴国内外经验完善退伍军人荣誉奖励制度", "丙省挑选部分国有企业开展混合所有制改革工作", "丁省为推动文化产业发展设立文化产业创新基地"], "a": 2, "e": "【C】本题考查政治常识。“政策试点”，是中国治理实践中所特有的一种政策测试与创新机制，具体类型包括各种形式的试点项目、试验区等。试点项目是中国政策过程中最为典型和普遍的一种政策试点类型，它是指在一定时间段和一定范围（特定的地域、政府部门或企事业单位）内所进行的一种局部性政策探索及实施活动。住建部挑选9个城市先行开展规范城市户外广告设施管理工作就是一种试点项目。A项错误，甲省的政策面对的是甲省全部的高新企业，与题干政策不是同一类。B项错误，乙省的政策面对的乙省全部的退伍军人，与题干政策不是同一类。C项正确，“挑选部分国有企业”也是一种试点项目政策。D项错误，“设立文化产业创新基地”属于设立试验区，试验区是指为探索或实施某一项或某一领域的新政策、新制度而选定的一个地域性区划单位，具体表现为各种样式的综合性试验区、专门性试验区以及特区、新区、开发开放区、示范区、合作区等。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-16", "q": "党的十八大从国家、社会、个人三个层面对社会主义核心价值观作了阐述，从个人层面倡导的是：", "options": ["富强、民主、文明、和谐", "自由、平等、公正、法治", "爱国、敬业、诚信、友善", "和平、发展、合作、共赢"], "a": 2, "e": "【C】本题考查政治常识。社会主义核心价值观是社会主义核心价值体系的内核。党的十八大提出，社会主义核心价值观的基本内容是倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。A项错误，富强、民主、文明、和谐是国家层面的价值目标。B项错误，自由、平等、公正、法治是社会层面的价值取向。C项正确，爱国、敬业、诚信、友善是公民个人层面的价值准则。D项错误，不属于社会主义核心价值观的基本内容。十八大报告指出，中国将继续高举和平、发展、合作、共赢的旗帜，坚定不移地致力于维护世界和平、促进共同发展。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-17", "q": "党的十八届五中全会提出了引领中国发展的“五大理念”，即创新、协调、绿色、开放、共享。下列发展举措中，不符合“五大理念”的是：", "options": ["实施“京津冀一体化”“长江经济带”战略", "把发展、民生、社会建设融为一体，减少贫困人口", "充分利用劳动力资源丰富优势，大力发展生产要素驱动的作用", "推动建立绿色低碳循环发展产业体系，实施近零碳排放区示范工程"], "a": 2, "e": "【C】C项所述的劳动力生产要素驱动型产业属于落后的、低端的产业模式，是当下需要进行改革优化部分，不符合“五大理念”中创新的要求，当选。A项“京津冀一体化”、“长江经济带”战略体现了“五大理念”中协调、共享的理念，排除；B项把发展、民生、社会建设融为一体体现了“五大理念”中协调的理念，排除；D项推动建立绿色低碳循环发展产业、实施近零碳排放区示范工程体现了“五大理念”中绿色的理念，排除。本题为选非题，故正确答案为C。", "tag": "政治常识"},
{"id": "pol-18", "q": "下列关于党的重要思想，按提出时间先后顺序排列正确的是：①社会主义市场经济理论②“三个代表”重要思想③社会主义本质理论④构建社会主义和谐社会理念", "options": ["①②③④", "①②④③", "③①②④", "③②①④"], "a": 2, "e": "【C】①社会主义市场经济理论：1992年10月12日，中共十四大报告明确指出，中国经济体制改革的目标是建立社会主义市场经济体制，以利于进一步解放和发展生产力。②“三个代表”重要思想：2000年2月，江泽民在广东考察工作，第一次提出“三个代表”要求。2002年11月，江泽民在党的十六大报告中进一步阐述了“三个代表”重要思想的时代背景、历史要求、指导意义。党的十六大把“三个代表”重要思想同马克思列宁主义、毛泽东思想、邓小平理论一道，确立为党必须长期坚持的指导思想并写入党章。③社会主义本质理论：1992年初，邓小平在“南方谈话”中提出：“社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕”。④构建社会主义和谐社会理念：2004年9月19日，党的十六届四中全会第一次明确提出，共产党作为执政党，要“坚持最广泛最充分地调动一切积极因素，不断提高构建社会主义和谐社会的能力”。这是在党的文件中第一次把和谐社会建设放到同经济建设、政治建设、文化建设并列的突出位置。由此可知，按照提出时间从先至后顺序为③①②④。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-19", "q": "耕地保护是关系我国经济和社会可持续发展的全局性战略问题。“十分珍惜和合理利用土地，切实保护耕地”是必须长期坚持的一项基本国策。下列说法不正确的是：", "options": ["耕地占用补偿制度是我国目前主要的耕地保护制度之一", "国家能源、交通、水利、军事等重点建设项目确需占用基本农田的，必须报省级政府批准", "补充耕地任务全面落实是“十二五”期间土地整治的主要目标之一", "我国耕地保护红线是18 亿亩"], "a": 1, "e": "【B】我国人口多耕地少，耕地后备资源不足，维护国家粮食安全，保持社会稳定，始终是我国的一个重大问题。为此，国家专门制定《基本农田保护条例》，划定基本农田保护区，其根本目的就是为了对基本农田实行特殊保护，以满足我国未来人口和国民经济发展对农产品的需求，为农业生产乃至国民经济的持续、稳定、快速发展起到保障作用。其中第三章第十五条规定：“基本农田保护区经依法划定后，任何单位和个人不得改变或者占用。国家能源、交通、水利、军事设施等重点建设项目选址确实无法避开基本农田保护区，需要占用基本农田，涉及农用地转用或者征收土地的，必须经国务院批准。”B项错误，A、C、D三项正确。本题为选非题，故正确答案为B。", "tag": "政治常识"},
{"id": "pol-20", "q": "社会主义核心价值观的基本内容概括为24 个字：富强、民主、文明、和谐；自由、平等、公正、法治；爱国、敬业、诚信、友善。其中，对公民个人层面的价值准则的要求是：", "options": ["富强、民主、文明、和谐", "自由、平等、公正、法治", "爱国、敬业、诚信、友善", "公正、法治、爱国、敬业"], "a": 2, "e": "【C】培育和践行社会主义核心价值观，是推进中国特色社会主义伟大事业、实现中华民族伟大复兴中国梦的战略任务。党的十八大提出，倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。这与中国特色社会主义发展要求相契合，与中华民族优秀传统文化和人类文明优秀成果相承接，是我们党凝聚全党全社会价值共识作出的重要论断。富强、民主、文明、和谐是国家层面的价值目标，自由、平等、公正、法治是社会层面的价值取向，爱国、敬业、诚信、友善是公民个人层面的价值准则，这24个字是社会主义核心价值观的基本内容，为培育和践行社会主义核心价值观提供了基本的遵循方向。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-21", "q": "补精神之钙、除“四风”之害、立为民之制为重点，突出作风建设。“四风”是指：", "options": ["形式主义、官僚主义、享乐主义、奢靡之风", "主观主义、宗派主义、官僚主义、享乐主义", "主观主义、形式主义、官僚主义、享乐主义", "形式主义、官僚主义、宗派主义、奢靡之风"], "a": 0, "e": "【A】“四风”指形式主义、官僚主义、享乐主义和奢靡之风。由习近平2013年6月18日在北京召开的中国共产党的故正确答案为A。", "tag": "政治常识"},
{"id": "pol-22", "q": "党的十八大提出“扎实推进社会主义文化强国建设”，指出要推动学雷锋活动，学习宣传道德模范：", "options": ["长效化", "广泛化", "具体化", "常态化"], "a": 3, "e": "【D】愿服务，推动学雷锋活动、学习宣传道德模范常态化”。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-23", "q": "2013 年高考前夕，一则消息让广大农村考生感到温暖和振奋：国家决定，提高重点高校招收农村学生比例，今年比去年增加8.6%。这主要体现了：", "options": ["党和政府维护社会公平", "党和政府以人为本的执政理念", "党和政府求真务实的工作作风"], "a": 0, "e": "【A】我国的农村学生不能与城市学生一样公平地享受教育资源，而且存在教育投入不足且不合理、大学学费和各种费用不断攀升、高考限制农村学生比例等问题。2013年5月15日，国务院总理李克强主持召开国务院常务会议，决定进一步提高重点高校招收农村学生比例。根据国务院第一次全体会议关于促进教育公平的部署和要求，要使更多优质高等教育资源惠及农村、边远、贫困、民族地区的农家子弟，让更多勤奋好学的农村孩子看到希望。这是实现社会公平的重要途径。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-24", "q": "以下关于低碳发展叙述正确的是：", "options": ["历史上的全球累计碳排放主要是由发展中国家造成的", "“十二五”期间我国要实现单位国内生产总值耗能减低25%", "我国首个获得财政部和环保部批准的综合性排放权交易机构是南京排放权交易所", "到2020 年我国碳排放降低的目标是：单位国内生产总值的二氧化碳排放量比2005 年下降40%~45%"], "a": 3, "e": "【D】A项错误，历史上主要是由现在的西方发达国家在发展过程中，随着工业革命的开展，煤炭的大量使用而造成的；B项错误，“十二五”期间我国要实现单位国内生产总值能耗降低16%；C项错误，我国首个获得财政部和环保部批准的综合性排放权交易机构是天津排放权交易所；D项正确，全国人大常委会作出了决议，到2020年我国单位国内生产总值二氧化碳排放比2005年下降40%-45%。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-25", "q": "我国目前仍是城乡发展不平衡的发展中国家，农业基础依然薄弱，农民增收的长效机制尚未真正建立起来，解决好“三农”问题任重道远，解决“三农”问题的根本途径是：", "options": ["工业反哺农业", "建设社会主义新农村", "城乡发展一体化", "建立农民增收的长效机制"], "a": 2, "e": "【C】十八大报告指出，解决好农业农村农民问题是全党工作的重中之重，要坚持走中国特色农业现代化道路，并要把推动城乡发展一体化作为解决“三农”问题的根本途径。报告指出，要加大统筹城乡发展力度，增强农村发展活力，逐步缩小城乡差距，促进城乡共同繁荣。加快完善城乡发展一体化体制机制，着力在城乡规划、基础设施、公共服务等方面推进一体化，促进城乡要素平等交换和公共资源均衡配置，形成以工促农、以城带乡、工农互惠、城乡一体的新型工农、城乡关系。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-26", "q": "下列属于贯彻落实党的十八大“全面提高党的建设科学”的是：", "options": ["作出在全党开展深入学习实践科学发展观活动的部署", "提出建设马克思主义学习型政党、建设学习型党组织", "开展创建先进基层党组织、争当优秀共产党员的活动"], "a": 2, "e": "【C】的八项规定。而A、B、D三项的阐述在十八大之前就提出了，题目的题眼是“贯彻落实党的十八大”，根据时间顺序，可将正确答案定位为C项。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-27", "q": "近年来，我国通过“三下乡”活动，把发展经济、建设小康和扶贫攻坚结合起来，为农村中心工作服务。“三下乡”是指文化、科技、（）三下乡。", "options": ["卫生", "教育", "人才", "金融"], "a": 0, "e": "【A】“三下乡”即有关文化、科技、卫生方面的内容知识向农民普及，促进农村文化、科技、卫生的发展。大力开展文化、科技、卫生“三下乡”活动，是我们党全心全意为人民服务宗旨的具体体现。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-28", "q": "党中央、国务院把“三农”问题作为全国工作的重中之重，明确提出了城乡统筹发展的基本方略，制定了“工业反哺农业、城市支持乡村”和（）的基本方针。", "options": ["“多予、少取、放活”", "“改革、创新、搞活”", "“互惠互利、相互促进、协调发展”", "“先富带后富，最终实现共同富裕”"], "a": 0, "e": "【A】城乡统筹发展的基本方针有三点——工业反哺农业、城市支持乡村和多予、少取、放活。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-29", "q": "2012 年中共十八大报告首次正式作出一项涉及党内民主机制的重要决定，使推进党内民主有了新渠道，标志着党内民主又迈出了具有划时代意义的一步。该项重要决定是：", "options": ["党代表任期制度", "党代表提案制度", "党代表常任制度", "党代表专职制度"], "a": 1, "e": "【B】十八大报告提出实行“党代会代表提案制”，这是中共首次正式作出该项涉及党内民主机制的重要决定。故正确答案为B。胡锦涛同志在十八大报告中强调，党内民主是党的生命。要坚持民主集中制，健全党内民主制度体系，以党内民主带动人民民主。保障党员主体地位，健全党员民主权利保障制度，开展批评和自我批评，营造党内民主平等的同志关系、民主讨论的政治氛围、民主监督的制度环境，落实党员知情权、参与权、选举权、监督权。完善党的代表大会制度，提高工人、农民代表比例，落实和完善党的代表大会代表任期制，试行乡镇党代会年会制，深化县（市、区）党代会常任制试点，实行党代会代表提案制。", "tag": "政治常识"},
{"id": "pol-30", "q": "科学发展观的核心是，基本要求是。", "options": ["以人为本全面协调可持续", "发展全面协调可持续", "以人为本统筹兼顾", "发展统筹兼顾"], "a": 0, "e": "【A】本题考查科学发展观的要点。科学发展观的第一要务是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-31", "q": "十八大报告提出，要建设学习型、服务型、创新型的马克思主义执政党，必须全面加强党的思想建设、组织建设、作风建设、制度建设和（）。", "options": ["反腐倡廉建设", "民主建设", "纪律建设", "文化建设"], "a": 0, "e": "【A】胡锦涛总书记在十八大报告提出，要建设学习型、服务型、创新型的马克思主义执政党，必须全面加强党的思想建设、组织建设、作风建设、制度建设和反腐倡廉建设。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-32", "q": "十八大报告指出，要建设学习型、服务型、创新型的马克思主义执政党，必须全面加强党的思想建设、组织建设、作风建设、制度建设和：", "options": ["文化建设", "反腐倡廉建设", "纪律建设", "民主建设"], "a": 1, "e": "【B】胡锦涛同志在十八大指出：全党要增强紧迫感和责任感，牢牢把握加强党的执政能力建设、先进性和纯洁性建设这条主线，坚持解放思想、改革创新，坚持党要管党、从严治党，全面加强党的思想建设、组织建设、作风建设、反腐倡廉建设、制度建设，增强自我净化、自我完善、自我革新、自我提高能力，建设学习型、服务型、创新型的马克思主义执政党，确保党始终成为中国特色社会主义事业的坚强领导核心。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-33", "q": "党的十八大提出，党要坚持解放思想、改革创新，坚持党要管党、从严治党，全面加强党的思想建设、组织建设、作风建设、（）、制度建设，增强自我净化、自我完善、自我革新、自我提高能力，建设学习型、服务型、创新型的马克思主义执政党。", "options": ["民主建设", "纪律建设", "反腐倡廉建设", "法制建设"], "a": 2, "e": "【C】党的十八大提出，“全党要增强紧迫感和责任感，牢牢把握加强党的执政能力建设、先进性和纯洁性建设这条主线，坚持解放思想、改革创新，坚持党要管党、从严治党，全面加强党的思想建设、组织建设、作风建设、反腐倡廉建设、制度建设，增强自我净化、自我完善、自我革新、自我提高能力，建设学习型、服务型、创新型的马克思主义执政党，确保党始终成为中国特色社会主义事业的坚强领导核心。”故正确答案为C。", "tag": "政治常识"},
{"id": "pol-34", "q": "社会主义和谐社会的核心价值是：", "options": ["以民为本", "社会稳定", "诚实守信", "公平正义"], "a": 3, "e": "【D】社会和谐是中国特色社会主义的本质属性，是国家富强、民族振兴、人民幸福的重要保证。公平正义是和谐社会的核心价值取向，因为公平正义是社会主义本质的根本要求，是维护社会稳定的前提条件，是坚持以人为本的重要表现。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-35", "q": "国家“十二五”规划纲要提出，要积极稳妥推进城镇化，把（）作为推进城镇化的重要任务。", "options": ["符合落户条件的农业转移人口逐步转为城镇居民", "促进农村转移人口城镇就业", "合理控制大中城市的农业转移人口流入", "鼓励和支持中西部地区、中小城市发展"], "a": 0, "e": "【A】国家“十二五”规划纲要第二十章第二节明确指出：把符合落户条件的农业转移人口逐步转为城镇居民作为推进城镇化的重要任务。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-36", "q": "中国共产党十七届六中全会提出建设社会主义（）和到2020 年的文化改革发展的奋斗目标。", "options": ["科技强国", "人才强国", "文化强国", "创新强国"], "a": 2, "e": "【C】十七届六中全会通过的《中共中央关于深化文化体制改革、推动社会主义文化大发展大繁荣若干重大问题的决定》中提出要努力建设社会主义文化强国，并提出了到2020年的文化改革发展奋斗目标。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-37", "q": "中国特色社会主义“四位一体”建设指：", "options": ["经济建设、政治建设、道德建设、社会建设", "经济建设、政治建设、文化建设、社会建设", "经济建设、政治建设、法治建设、文化建设", "经济建设、政治建设、社会建设、生态建设"], "a": 1, "e": "【B】2005年10月党的十六届五中全会的会议中，把我国社会主义建设任务进一步表述为“社会主义经济建设、政治建设、文化建设和社会建设”。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-38", "q": "和谐社会可以理解为：", "options": ["西方社会的“福利社会”", "社会主义的治国思想", "我国古代社会描写的“田园牧歌”", "“大同”社会"], "a": 1, "e": "【B】人类社会是一个不断从低级向高级发展的历史过程。实现社会和谐，建设美好社会，始终是人类孜孜以求的一个社会理想，也是包括中国共产党在内的马克思主义政党不懈追求的一个社会理想。对于中国共产党人来说，构建社会主义和谐社会，既是一种治国理想，又是一种治国方略、治国机制，也是一种治国结果，是目标与过程的统一，符合人类历史发展的规律。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-39", "q": "下列事件按时间先后顺序排列正确的是：①十一届三中全会召开②家庭联产承包责任制确立③开始设立经济特区④提出“一个中心，两个基本点”", "options": ["①②③④", "②①③④", "①③②④", "①④②③"], "a": 2, "e": "【C】本题考查政治常识。①中国共产党第十一届中央委员会第三次全体会议简称十一届三中全会，于1978年12月18日-22日在北京举行。②家庭联产承包责任制是80年代初期，在中国大陆农村推行的一项重要的改革，是农村土地制度的一项转折，1978年从安徽省凤阳县小岗村开始试点，1982年家庭联产承包责任制确立。③1980年5月，中共中央和国务院决定将深圳、珠海、汕头和厦门四个出口特区改称为经济特区，这是我国设立经济特区的开始。④“一个中心”指以经济建设为中心，“两个基本点”指坚持四项基本原则、坚持改革开放。在1987年中国共产党第十三次全国代表大会作出这一概括。故正确排序应为①③②④。A、B、D三项错误，C项正确。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-40", "q": "党在社会主义初级阶段的基本路线是坚持“一个中心，两个基本点”，其中“一个中心”是指以（）为中心。", "options": ["经济建设", "政治建设", "文化建设", "党风建设"], "a": 0, "e": "【A】“一个中心，两个基本点”是邓小平在十三大提出的。“一个中心”即以经济建设为中心。这一中心的确立，是在对我国社会主义建设经验教训科学总结的基础上作出的正确选择，充分体现了社会主义本质的要求，是解决我国现阶段社会主要矛盾的根本途径。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-41", "q": "下列论断属于邓小平同志在1992 年“南方谈话”时提出的是：", "options": ["社会主义首先要发展生产力", "社会主义也可以搞市场经济", "中国要警惕“右”，但主要是防止“左”", "搞建设至少不比搞革命容易"], "a": 2, "e": "【C】本题考查政治常识。A项错误，“社会主义首先要发展生产力”是邓小平在1980年提出的重要论断；B项错误，“社会主义也可以搞市场经济”是邓小平于1979年11月26日在《社会主义也可以搞市场经济》一文中提出的重要论断；C项正确，面对90年代初党内出现的一些问题，邓小平同志从中国的历史和现实出发，从改革开放和现代化建设的任务出发，在南巡途中提出了“中国要警惕‘右’，但主要是防止‘左’”；D项错误，“搞建设不比搞革命容易”是邓小平在1957年提出来的论断。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-42", "q": "针对我国疫情防控工作，习近平总书记指出“要变压力为动力，善于化危为机”。以下典故与“善于化危为机”所蕴含的哲学原理一致的是（）。", "options": ["塞翁失马，焉知非福", "绳锯木断，水滴石穿", "千里之堤，溃于蚁穴", "南橘北枳，便分两等"], "a": 0, "e": "【A】本题考查政治常识。唯物辩证法认为矛盾双方相互贯通，在一定条件下可以相互转化。“要变压力为动力，善于化危为机”体现了矛盾双方在一定条件下的相互转化。A项正确，“塞翁失马，焉知非福”比喻一时虽然受到损失，反而因此能得到好处。也指坏事在一定条件下可变为好事，反之亦然。体现了矛盾双方在一定条件下可以相互转化。B项错误，“质量互变规律”是唯物辩证法三大基本规律之一，强调量变是质变的必要准备，质变是量变的必然结果，量变超过一定限度必然引起质变，使旧质变为新质，然后在新质基础上又开始新的量变。“绳锯木断，水滴石穿”意思是用绳子也能把木头锯断，水珠滴落，天长日久也可以把石头滴穿。体现了质量互变规律。C项错误，“千里之堤，溃于蚁穴”意思是千里长的大堤，往往因蚂蚁（白蚁）洞穴而崩溃。比喻小事不慎将酿成大祸。体现了质量互变规律。D项错误，唯物辩证法强调内因是事物变化的根据，外因是事物变化的条件，外因通过内因而起作用。“南橘北枳，便分两等”比喻同一物种因环境条件不同而发生变异。体现了外因是事物发展的重要条件。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-43", "q": "2019 年5 月31 日，习近平总书记在“不忘初心、牢记使命”主题教育工作会议上发表重要讲话指出，要坚持思想建党、理论强党，坚持学思用贯通、知信行统一，推动广大党员干部筑牢信仰之基、补足精神之钙、把稳思想之舵。这段话体现的哲学原理是①社会存在决定社会意识②精神对物质、社会意识对社会存在具有反作用③矛盾无时无处不在，具有普遍性和客观性④先进的社会意识对社会发展起推动作用", "options": ["①④", "②③", "①③", "②④"], "a": 3, "e": "【D】本题考查政治常识。①错误，社会存在决定社会意识，社会意识是社会存在的反映，社会存在的性质和变化决定社会意识的性质和变化。题干并未体现。②④正确，精神（意识）对物质具有反作用，社会意识具有相对独立性，社会意识反映社会存在并对社会存在起促进或阻碍的作用，先进的社会意识对社会发展起推动作用。习近平总书记这句话的意思是广大党员干部要以党的理论武装头脑，学习并树立先进的社会意识，发挥主观能动性，利用意识对物质的反作用，才能更好地认识世界、改造世界，才能③错误，矛盾指事物自身所包含的既相互排斥又相互吸引、既对立又统一的趋势、倾向和方面。矛盾是客观事物所固有的，具有客观性、普遍性。题干并未体现。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-44", "q": "习近平总书记在《辩证唯物主义是中国共产党人的世界观和方法论》一文中指出，“学习和运用唯物辩证法，就要反对形而上学的思想方法”。中国古代成语中，就有对形而上学思想的批判，下列成语中不属于对形而上学思想批判的是：", "options": ["盲人摸象、刻舟求剑", "缘木求鱼、邯郸学步", "坐井观天、水中捞月", "老骥伏枥、老马识途"], "a": 3, "e": "【D】本题考查政治常识。形而上学是与辩证法相对立的世界观和方法论。其特点是用孤立、静止、片面观点来看世界。A项正确，盲人摸象，意思是比喻对事物只凭片面的了解或局部的经验，就乱加猜测，想做出全面的判断，以偏概全，不能了解真相，是片面地看待事物。刻舟求剑一般比喻死守教条，拘泥成法，固执不变通的人，忽视了运动是物质的根本属性。两个典故都属于对形而上学思想的批判。B项正确，缘木求鱼，比喻方向或办法不对头，不可能达到目的。邯郸学步，比喻一味地模仿别人，不仅没学到本事，反而把原来的本事也丢了。两个典故都体现了没有把握事物本质，片面地看问题，都属于对形而上学思想的批判。C项正确，坐井观天，比喻眼界小，见识少。水中捞月，比喻去做根本做不到的事情，只能白费力气。两个典故都体现了用片面的、孤立的观点看问题，都属于对形而上学思想的批判。D项错误，老骥伏枥，比喻有志向的人虽然年老，仍有雄心壮志，蕴含着自强不息的民族精神。老马识途，意思是指老马认识路，比喻有经验的人对事情比较熟悉。两个典故属于辩证法的观点，不属于对形而上学思想的批判。本题为选非题，故正确答案为D。", "tag": "政治常识"},
{"id": "pol-45", "q": "的马克思主义基本原理是②从认识到实践、从实践到认识③个别与一般内在统一并紧密相连④从物质到精神、从精神到物质", "options": ["①②③", "①②④", "①③④", "②③④"], "a": 2, "e": "【C】本题考查政治常识。活动主体原理。而选项表述错误，应当是“从实践到认识，再从认识到实践”。③中去的领导方法体现了从个别到一般，从一般到个别。质到精神，精神到物质。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-46", "q": "习近平总书记在庆祝改革开放40 周年大会上的讲话中，引用了恩格斯的名言：“一切社会变迁和政治变革的终极原因，不应当到人们的头脑中，到人们对永恒的真理和正义的日益增进的认识中去寻找，而应当到生产方式和交换方式的变更中去寻找。”这句话蕴含的哲理是", "options": ["社会存在决定社会意识", "经济基础决定上层建筑", "主要矛盾决定根本任务", "社会实践决定认识成果"], "a": 1, "e": "【B】本题考查政治常识。题干中习近平总书记讲到：“不应当到而应当到”强调的是“而应当到”后面的内容，即“生产方式和交换方式的变更中去寻找”。生产方式是指社会生活所必需的物质资料的谋得方式，在生产过程中形成的人与自然界之间和人与人之间的相互关系的体系。人们一般把物质资料生产的物质内容称作是生产力，把其社会形式称作是生产关系，这两者都是生产方式的建设性内容——物质生产方式（物质谋得方式）和社会生产方式（社会经济活动方式）。换言之，生产方式是两者在物质资料生产过程中的能动统一。A项错误，社会存在是指社会的物质生活过程，其基础及决定力量是物质资料的生产方式；社会意识是指社会的精神生活过程。社会存在决定社会意识，是指社会存在是第一性的，它决定社会意识。题干信息未体现这一哲学原理。B项正确，经济基础是指由社会一定发展阶段的生产力所决定的生产关系的总和，是构成一定社会的基础；上层建筑是建立在经济基础之上的意识形态以及与其相适应的制度、组织和设施。本题中，“生产方式和交换方式”属于经济基础范畴，“社会变迁和政治变革”属于上层建筑范畴，题干习总书记的这句话体现了经济基础决定上层建筑。C项错误，党的十九大报告指出“中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。”题干信息未体现主要矛盾问题。D项错误，实践对认识具有决定作用：实践是认识的来源，实践是认识发展的动力，实践是认识的目的，实践又是检验认识正确与否的唯一标准。因此，我们要树立实践第一的观点。题干信息未体现这一哲学原理。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-47", "q": "在20 世纪60 年代，焦裕禄成为那个时代精神的象征。今天，我们仍然敬仰焦裕禄，最主要是因为他身上折射着：", "options": ["为万世开太平的责任意识", "勇于创新的时代精神", "己所不欲勿施于人的理性精神", "强烈的社会责任感和历史使命感"], "a": 3, "e": "【D】焦裕禄，革命烈士。1946年加入中国共产党，1962年被调到河南省兰考县担任县委书记。时值该县遭受严重的顽强斗争，努力改变兰考面貌。他身患肝癌，依旧忍着剧痛，坚持工作，被誉为“党的好干部”“人民的好公仆”，折射着强烈的社会责任感和历史使命感。他用自己的实际行动，铸就了亲民爱民、艰苦奋斗、科学求实、迎难而上、无私奉献的焦裕禄精神。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-48", "q": "“有时候文明只是十公分的宽度，有时候只是一张纸的厚度，当我们把十公分的盲道让出来，当我们在椅子上垫一张纸，每个人的一小步构成了中国文明进步的一大步。”这段话蕴含的道理是：", "options": ["质变是量变的结果，要重视量的积累", "只要抓住时机，就能实现事物的质变", "要注重系统内部结构的优化趋向", "要立足整体，发挥整体统率作用"], "a": 0, "e": "【A】A项正确：每个人的一小步累积起来就是量变，量变达到一定量的积累就会引起质变，一小步的积累达到量变引起文明一大步的质变，质变是量变的结果。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-49", "q": "《荀子·儒效》中写道，“不闻不若闻之，闻之不若见之，见之不若知之，知之不若行之”。关于这句论述反映的思想，下列说法错误的是：", "options": ["知行合一", "实践出真知", "人定胜天", "实践决定认识"], "a": 2, "e": "【C】本题考查政治常识。“不闻不若闻之，闻之不若见之，见之不若知之，知之不若行之”意思是：学习中听说比不听好，见到比听说好，知晓比见到好，实践比知晓好，学习的最终就是实践，实践了，就明白了。反映了实践和认识的辩证关系，实践是认识的基础，实践决定认识。认识对实践有反作用，正确的认识、科学的理论对实践有指导作用。错误的认识、不科学的理论对实践有阻碍作用。A项正确，“知”就是知识，理论；“行”指行为，也就是实践。“知行合一”就是要将理论转化为实践，而且实践是理论的具体体现，是题干所反映的实践和认识的辩证关系。B项正确，题干反映了任何事情只有通过自己亲自尝试、实践，才能真正地认识、理解、掌握。即“实践出真知”。C项错误，“人定胜天”过分夸大了主观能动性，否认了规律的客观性。主观能动性的发挥要受到客观条件的制约。D项正确，题干反映了实践是认识的基础，实践决定认识。本题为选非题，故正确答案为C。", "tag": "政治常识"},
{"id": "pol-50", "q": "“你最痛苦的时候，窗外有小鸟在快乐地歌唱”这句格言的寓意是：", "options": ["学习小鸟快乐生活", "世界的本质是客观的", "人的尊严在于思想", "思维是客观存在的反应"], "a": 1, "e": "【B】A项错误，A项是表面意思，排除；B项正确，题目中这句格言的含义是主观上的情绪不会影响到别人，引申开来就是讨论主观与客观的关系。马克思辩证唯物主义认为，物质是世界的唯一本原。世界上的事物的具体形态和性质是无限多样的。但是客观实在性是它们最一般的共同本原和特性，也就是说世界的多样性统一于物质性，这与B项描述符合，当选；C项错误，题目并没有这个意思，排除；D项错误，D项虽然表述正确，但不是文中格言所表达的含义，排除。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-51", "q": "柏拉图认为处于变化之中的事物不是真正的存在，持这种理念的人会认为以下哪项最真实？", "options": ["一棵树", "勾股定理", "人的照片", "关于马的概念"], "a": 1, "e": "【B】B项正确：勾股定理是一个基本的几何定理，是人类早期发现并证明的重要数学定理之一。这条定理是既定的、不变的，按照题干中柏拉图的观点，勾股定理是真正存在的，当选；A项错误：一棵树从生根到发芽再到枝繁叶茂，是处在不断生长、不断变化的状态之中的，排除；C项错误：人的照片虽然定格了人一瞬间的样子，但照片会随着时间变得陈旧褪色，即不断发生变化，排除；D项错误：语言文字会随着社会发展而不断发生变化，关于“马”的概念也是这样，随着人们对事物的认识不断更新，“马”的概念也在不断变化，排除。故正确答案为B。本题为争议题，争议答案为D项。根据柏拉图本人的观点，马的概念是永恒不变的。但本题问的是持柏拉图的理念的一类人的看法，本题中，柏拉图认为处于变化之中的事物不是真正的存在，也就是说，真正的存在是静止不变的。四个选项中，只有B项更符合上述题干给出的论断，故粉笔题库倾向于答案为B。", "tag": "政治常识"},
{"id": "pol-52", "q": "下列与哲学有关的说法正确的是：", "options": ["“感觉是人与世界之间的屏障”是不可知论的观点", "从哲学角度来看，“机不可失，时不再来”说明了时间的绝对性", "“不识庐山真面目，只缘身在此山中”说明真理是具体和多元的"], "a": 0, "e": "【A】本题考查的是马克思主义的相关知识。A项正确，“感觉是人与世界之间的屏障”，是哲学家休谟的观点，他认为人的感觉把人对世界的认识隔离开来了，其本质特点是否定了人的认识与客观世界的统一性，属于不可知论的观点。B项错误，“千军易得，一将难求”这一谚语说的是千万人的军队容易组建,而能统帅千军的杰出将领却难以寻求，以此故不是历史唯心主义观点。C项错误，“机不可失，时不再来”指时机难得，必需抓紧，不可错过。体现了时间的不可逆性，说明时间具有一维性，而非绝对性。D项错误，“不识庐山真面目，只缘身在此山中”，意思是我之所以认不清庐山本来的面目，是因为我自己身在庐山之中。这就告诉我们由于人们所处的地位不同，看问题的出发点不同，对客观事物的认识难免有一定的片面性。因此要认识事物的真相与全貌，必须超越狭小的范围，摆脱主观成见。故没有体现真理的观点。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-53", "q": "港珠澳大桥是世界上最长的跨海大桥，大桥路线呈“S”型曲线，切合了水流走向。从结构力学的角度来看，弯度明显更稳定，跨海大桥受到的海浪冲击远远大于普通桥梁，设计“S”型曲线，能让水流通过引导减少对桥梁造成的伤害。同时，由于海底也和地面一样，是凹凸不平的地形，把桥梁修成弯曲的形状是为了避开这些起伏的地形，保障桥梁的稳定和安全。这表明：", "options": ["人具有主观能动性，可以认识事物的本质和规律", "人能够创造条件，改变规律起作用的具体方式", "人的意识能够创造出自然界所没有的客观事物", "人能够通过想象将观念中的对象变成现实的东西"], "a": 0, "e": "【A】本题考查政治常识。A项正确，人具有主观能动性，可以认识事物的本质和规律，并且能够利用规律，改造客观世界，造福于人类。港珠澳大桥路线设计成“S”型曲线正是人们利用规律，发挥主观性的一个体现。B项错误，人们可以创造条件，改变规律起作用的具体方式，但是本题大桥设计成“S”型曲线是人们在利用规律、顺应规律，并没有为了让规律起作用而去改变什么。C项错误，辩证唯物主义认为，物质决定意识，意识是对物质的反映，意识不是自生的和先验的。“意识能够创造出自然界所没有的客观事物”是唯心主义的观点，是错误的，意识不能够脱离物质而存在。D项错误，人能够通过想象将观念中的对象变成现实的东西，体现的是意识对物质的反作用，但题干没有提到人的想象，是无关选项，所以不选。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-54", "q": "下列语句与哲学原理对应错误的是：", "options": ["横切牛羊竖切猪，要省力气看纹路——办事要按客观规律", "工欲善其事，必先利其器——主观能动性发挥受客观条件限制", "破屋更遭连夜雨，漏船又遇打头风——事物发展是前进性与曲折性的统一", "不登高山，不知天之高也；不临深渊，不知地之厚也——实践是真理来源"], "a": 2, "e": "【C】本题考查哲学原理，需结合选项具体分析。A项正确，做事情要按照客观规律，才能更加容易地完成。按照牛、羊、猪的原有纹路进行切割，会更加容易且省力气，遵循了客观规律。B项正确，在发挥主观能动性的同时，会受到客观条件的限制。想要完成一件事，如果没有很好的利器就不能很好地完成，表明了在发挥主观能动性的同时会受客观条件的限制。C项错误，屋子本来就破了，可是偏偏又赶上连夜下雨。船本来就漏水了，但是又赶上逆风航行。只体现出了事物发展过程中的曲折性，并未体现出前进性。D项正确，登高山才知天之高，临深渊才知地之厚，通过实践才能获得真理，说明了实践是真理的来源。本题为选非题，故正确答案为C。", "tag": "政治常识"},
{"id": "pol-55", "q": "下列流行语与其所反映的哲理对应错误的是：", "options": ["正能量——发挥社会意识正确导向作用", "新常态——静止的、无条件的", "中国式——共性寓于个性之中"], "a": 1, "e": "【B】A项正确，正能量指的是一种健康乐观、积极向上的动力和情感，对事物发展有积极作用，体现了“发挥社会意识的正确导向作用”的原理。B项错误，中国新常态要发挥对世界经济的正面效应，需要不断推进改革来驱动增长，这体现了“事物之间的联系具有条件性、多样性”的原理；在新常态下，中国经济结构调整的本质是资源要素的重新组合利用，资产重组调整再分配，是此消彼长的关系，这体现了“一切事物是变化发展的，发展具有普遍性”的原理；在新常态下新旧力量将长期并存，原有的对经济发展有影响的因素会继续发挥其效应，而新的特征和趋势也将逐步形成，新常态需要新思路和新方式，但不否定那些仍继续有效的做法，这体现了“矛盾具有普遍性、具体性”的原理。所以，B项错误，并未体现“静止的、无条件的”原理。D项正确，中国式是指具有中国特色的事物。共性指不同事物的普遍性质；个性指一事物区别于他事物的特殊性质，体现了“共性寓于个性之中”的原理。本题为选非题，故正确答案为B。", "tag": "政治常识"},
{"id": "pol-56", "q": "国产电影《哪吒之魔童降世》中，哪吒希望通过自己的努力改变他人成见，得到周围人的认可和喜爱。最终，在感受到父母的爱后，以一己之力对抗天命，保护家人周全，贴近当代年轻人的奋斗观和人生观，不信命，靠自己。哪吒“我命由我不由天”的呐喊，其合理性在于。", "options": ["只要有坚韧的意志，就能取得成功", "强大精神力量在改造世界的过程中有决定作用", "意识具有能动性，有能动地认识世界和改造世界的作用", "唯心主义在现实生活中有一定的应用价值"], "a": 2, "e": "【C】本题考查政治常识。A项错误，坚韧的意志是成功的基础，但要取得成功还需要能力、心态、智慧、机遇等各种因素，并不是只有坚韧的意志。选项表述有误，排除。B项错误，强大的精神力量作为一种意识，对人们的行为具有导向、规范作用，能够影响前途和命运，但并非在改造世界的过程中起到决定作用。选项表述有误，排除。C项正确，意识具有能动作用，一方面意识能够指导人们能动地认识世界；另一方面意识能够指导人们能动地改造世界（包括调节和控制人体生理活动）。哪吒希望通过自己的努力改变他人成见，这种意识指导他最终证明了自己，赢得人们的尊重。D项错误，唯心主义强调意识是世界的本原，世界上一切物质都是由于意识的存在而存在的，没有意识就没有物质。而唯物主义认为世界是物质的，物质第一性，意识第二性，在现实生活中我们应该用唯物主义来指导实践。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-57", "q": "荀子的“不闻不若闻之，闻之不若见之，见之不若知之，知之不若行之”；明代王夫之的“知行相资以为用”，从哲学的角度，这里主要强调的是。", "options": ["物质与意识", "认识与实践", "感性认识与理性认识", "静止与运动"], "a": 1, "e": "【B】本题考查政治常识。A项错误，世界统一于物质，意识是物质的产物，物质第一性，意识第二性，物质决定意识，意识对物质具有能动的反作用。意识的反作用要受物质决定作用的制约。题干未体现，无关选项。B项正确，实践对认识的决定性作用主要表现为：（1）实践是认识的来源，实践产生了认识的需要；（2）实践是认识发展的根本动力，是认识的基础；（3）实践是认识的目的；（4）实践是检验认识正确与否的唯一标准。荀子的“不闻不若闻之，闻之不若见之，见之不若知之，知之不若行之”，意思是没有听到不如听到，听到不如见到，见到不如理解到，理解到不如去实行，学问到了实行也就达到了顶点。王夫之的“知行相资以为用”，意思是以知促行、以行促知、知行合一。所以题干主要强调的是“认识与实践”的哲学原理。C项错误，感性认识是人们在实践过程中，通过自己各种感官产生的感觉在头脑中产生许多印象，对各种事物的表面现象有了初步认识。它只反映事物的现象和外部联系，尚未达到事物的本质和内部联系。在感性认识的基础上，经过思考的作用，将丰富的感觉材料，加以去粗取精，去伪存真，由此及彼，由表及里的改造制作过程，就会产生一个飞跃，变成由概念、判断和推理阶段反映事物的本质和内部联系的理性认识。它同感性认识有性质的不同，但又互相连贯，二者在实践的基础上联系起来。题干未体现，无关选项。D项错误，运动是物质的存在形式和固有属性。它包括宇宙间的一切变化和过程。辩证唯物主义认为，世界是物质的，物质是永恒运动着的。物质和运动是不可分的，世界上没有不运动的物质，也没有离开物质的运动。题干未体现，无关选项。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-58", "q": "“正能量”指的是一种健康乐观、积极向上的动力和情感。当下中国社会涌现了许多富有正能量的人和事，这些催人奋进的、充满希望的人和事也带动和影响了周围一批人，从哲学角度看（）。①正能量具有指导作用，能够将人们的愿望变成现实②正能量具有能动性，能够给人带来信心和力量③正能量具有反作用，能对人体生理活动进行调节和控制④正能量具有创造性，能直接转化为物质力量", "options": ["①②", "①④", "②③", "③④"], "a": 2, "e": "【C】该题考查政治相关知识。人能够能动地改造世界体现在：意识对改造客观世界具有指导作用；意识对于人体生理活动具有调节和控制作用。①错误，“正能量”是一种具有健康乐观、积极向上的意识，意识具有指导作用，人们在意识的指导下通过实践才能把观念的东西转化为现实东西，但是仅仅通过意识是无法将愿望变成现实的，前半句正确，后半句错误，所以①错误。②正确，“正能量”作为一种正确的意识，是一种健康乐观、积极向上的动力和情感，能够给人带来信心和力量，所以②正确。③正确，“正能量”作为一种正确的意识，健康乐观、积极向上的动力和情感，对人体生理活动具有调节和控制作用，当人们在遇到挫折困难的时候，可以通过“正能量”的意识，使人们积极乐观、身心愉悦，更好地面对生活。所以③正确。④错误，意识活动具有主动性和创造性，是人能够认识世界的重要条件，但是意识不能直接转化为物质力量，是通过实践才能转化为物质的，所以④错误。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-59", "q": "“鞋子合不合脚，自己穿着才知道，一个国家的发展道路合不合适，只有这个国家的人民才最有发言权。”下列古诗词蕴涵的哲理与“鞋子合脚论”最相近的是", "options": ["沉舟侧畔千帆过，病树前头万木春", "古歌新曲君休听，听取新翻杨柳枝", "问渠那得清如许，为有源头活水来", "纸上得来终觉浅，绝知此事要躬行"], "a": 3, "e": "【D】本题考查政治常识。A项错误，该句的意思是沉舟侧畔，有千帆竞发；病树前头，正万木皆春。体现的哲理是事物总是不断发展变化的，新事物必然战胜旧事物，新陈代谢是宇宙间不可抗拒的规律。B项错误，该句的意思是请你不要再吹奏前朝的曲子，来听听新创作的《杨柳枝》。体现的哲理是事物是变化发展的，不可因循守旧。C项错误，该句表面是写水因为有源头活水不断注入才“清如许”，实则说明了为学之道必须不断地吸收新的营养。体现的哲理是事物都是不断运动、变化和发展的，运动是物质的存在方式和根本属性。D项正确，该句的意思是从书本上得来的知识毕竟不够完善，要透彻地认识事物还必须亲自实践。体现的哲理是实践是认识的来源，是检验真理的唯一标准。题干中“鞋子合脚论”也体现了这一原理。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-60", "q": "1798 年，拉普拉斯曾根据牛顿引力理论预言宇宙中存在一种类似于黑洞的天体。1939 年，奥本海默等根据广义相对论，进一步证明，一个无压的尘埃球体，在自引力作用下将能坍缩到它的引力半径的范围以内，这就形成黑洞。2019 年4 月10 日，黑洞研究开创性成果——“虚拟望远镜”在2017 年拍摄的黑洞照片在全球同时发布，人们对于黑洞的研究又向前迈进了一步。这一过程蕴含的哲理是", "options": ["联系具有普遍性和条件性", "世界具有统一性和多样性", "认识具有反复性和上升性", "实践具有客观性和历史性"], "a": 2, "e": "【C】本题考查政治常识。A项错误，联系具有普遍性和条件性。世界上的一切事物都与周围其他事物有着这样或那样的联系。一切事物的存在和发展都是有条件的。但本题没有体现联系的普遍性和多样性。B项错误，世界具有物质统一性，世界的本原只有一个，即物质。而物质世界中各种事物和现象都是物质及其存在形式的不同表现。世界具有的统一性和多样性是共性和个性的关系。题干中没有体现世界的统一性和多样性。C项正确，认识具有反复性。人们对一个事物的正确认识往往要经过从实践到认识、再从认识到实践的多次反复才能完成。从实践到认识、从认识到实践的循环是一种波浪式的前进和螺旋式的上升。题干中对于黑洞从预言到如今照片发布的认识过程，体现了人类认识的反复性和上升性。D项错误，实践是人类改造客观世界的物质性活动，具有客观物质性和社会历史性。题干强调的是认识活动而非实践，故不选。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-61", "q": "恩格斯说：“对现存宗教进行斗争的实践需要，把大批最坚决的青年黑格尔分子推回到英国和法国的唯物主义。他们在这里跟自己的学派体系发生了冲突。唯物主义把自然界看做唯一现实的东西，而在黑格尔的体系中，自然界只是绝对观念的外化。”以上名言出自：", "options": ["《神圣家族》", "《路德维希·费尔巴哈与德国古典哲学的终结》", "《基督教的本质》", "《德意志意识形态》"], "a": 1, "e": "【B】本题考查马克思和恩格斯的相关著作知识。A项错误，《神圣家族》是马克思和恩格斯第一次合写的批判青年黑格尔派主观唯心主义和论述历史唯物主义的著作。列宁说它奠定了革命唯物主义的社会主义的基础。B项正确，《路德维希费尔巴哈与德国古典哲学的终结》是恩格斯的作品，阐明马克思主义哲学基本原理而写的一部重要的哲学著作。C项错误，《基督教的本质》是费尔巴哈的宗教哲学著作。在这部著作中，费尔巴哈从人本学唯物主义的立场出发，阐明了宗教神学的秘密，分析批判了基督教及神学，批驳了黑格尔思辨哲学关于基督教的错误观点。D项错误，《德意志意识形态》是马克思、恩格斯创立了历史唯物主义理论体系的一部巨著，标志着马克思主义哲学的成熟。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-62", "q": "爱因斯坦有言：在真理和认识方面，任何以权威者自居的人，必将在上帝的戏笑中垮台！对此，下列理解正确的是：①爱因斯坦否认世界是客观的②爱因斯坦否认物质世界存在规律性③爱因斯坦倾向于“意识会随着物质世界的发展而不断发展”的观点④爱因斯坦并不一定是有神论者，他所说的上帝不是人格化的神", "options": ["①②", "②③", "③④", "①④"], "a": 2, "e": "【C】本题考查政治常识。马克思主义认为：认识运动是一个实践、认识、再实践的不断反复的过程。一个正确的认识往往要经过多次反复以达到预期的结果为标志算完成，认识运动是无限发展、没有终点的。真理是人们对客观事物及其规律的正确反映。真理具有客观性，客观性是真理的根本属性。真理具有具体性，任何真理都是在一定时间、地点、条件下主观与客观的符合，它受条件的制约，并随条件的变化而变化，一切以时间、地点和条件为转移。爱因斯坦的名言“在真理和认识方面，任何以权威者自居的人，必将在上帝的戏笑中垮台”表述了认识是不断运动发展的，真理具有客观性与具体性。①②表述错误，题干信息既不能推断出爱因斯坦否认世界是客观的，也不能得出爱因斯坦否认物质世界存在的规律性。③表述正确，意识是随着物质世界的发展而不断变化发展的，任何“权威者”的认识都不是唯一的，永恒不变的，从“任何……，必将……垮台”等词就可以看出爱因斯坦倾向于“意识会随着物质世界的发展而不断发展”的观点。④表述正确，题干中的“上帝”并非是人格化的神，爱因斯坦仅仅只是以此来说明在真理和认识方面，没有所谓的“权威者”。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-63", "q": "在十三届全国人大一次会议上，宪法修正案经表决，获得高票通过。此次宪法修改的一项重要内容就是将习近平新时代中国特色社会主义思想载入国家根本法，体现党和国家事业发展的新成就、新经验、新要求，在总体保持宪法的连续性、稳定性、权威性的基础上推动宪法与时俱进，完善发展。宪法修改体现的哲理是：", "options": ["事物发展的本质是克服", "事物发展的本质是抛弃", "事物发展的本质是扬弃", "事物发展的本质是保留"], "a": 2, "e": "【C】本题考查哲学常识。发展是揭示事物运动、变化的整体趋势和方向性的范畴，发展是具有前进性质的运动，是事物由低级向高级、由简单向复杂、由无序向有序的上升运动。发展的实质是新事物的产生和旧事物的灭亡。扬弃指事物在新陈代谢过程中，发扬事物中的积极因素，抛弃旧事物中的消极因素。此次我国宪法修正案是在原有宪法基础上，根据党和国家事业发展的新成就、新经验、新要求进行完善发展，既保留了原宪法合理的内容，又与时俱进，体现了宪法的连续性、稳定性和与时俱进。A、B、D三项均表述错误，C项正确。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-64", "q": "国务院机构改革优化了创新引擎。一方面，重组科学技术部，加强、优化、转变政府科技管理和服务职能；另一方面，重组国家知识产权局，强化知识产权创造、保护和运用，让“第一动力”更有劲头。这段话蕴含的哲理是：", "options": ["社会存在状况决定社会意识", "上层建筑应与经济基础相适应", "生产关系应与生产力相适应", "社会意识一定要适应社会存在"], "a": 1, "e": "【B】本题考查哲学常识。A项错误，社会存在是指社会物质生活条件的总和，它包括地理环境、人口因素和生产方式。社会意识是社会生活的精神方面，是社会存在的总体反映。社会存在决定社会意识，但是本题没有体现社会存在和社会意识的辩证关系原理，而是强调对国家机构进行改革以促进科技创新发展。B项正确，上层建筑是指建立在一定经济基础上的社会意识形态以及与之相适应的政治法律制度，包括政治上层建筑和思想上层建筑。经济基础是指占统治地位的生产关系的总和。题干中的国家机构为经济发展、鼓励科技创新而进行改革，体现了调整上层建筑为经济基础服务。C项错误，生产力是人类改造自然并从自然界获得生存和发展的物质资料的能力。生产关系是人们在物质生产过程中所结成的经济关系。生产力决定生产关系，生产关系对生产力具有反作用。题干只是强调国家机构改革促进创新的发展，没有体现生产力和生产关系的辩证关系。D项错误，社会存在和社会意识的辩证关系为社会存在决定社会意识，社会意识对社会存在具有反作用，同时社会意识具有相对独立性。社会存在和社会意识的发展不完全同步，社会意识有时会先于社会存在，有时会落后于社会存在，选项表述太过绝对。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-65", "q": "公元前3 世纪，古希腊数学家欧几里得提出：“三角形内角之和等于180 度。”19 世纪，德国数学家黎曼提出：“在球面上，三角形内角之和大于180 度。”后来，俄国数学家罗巴切夫斯基又提出：“在凹面上，三角形内角之和小于180度。”这一认识过程说明", "options": ["真理具有绝对性", "真理具有唯一性", "真理具有客观性", "真理具有相对性"], "a": 3, "e": "【D】本题考查马克思主义哲学认识论的常识。A项错误，真理的绝对性是指任何真理都是对客观事物及其规律的正确反映，在它所适用的范围内是不能推翻的。选项说法正确，但与题干无关。B项错误，真理具有唯一性，是指对于一个确定的对象，在同一条件下得出的真理只有一个，不存在反映同一对象的相互矛盾的不同的真理。选项说法正确，但与题干无关。C项错误，真理具有客观性，真理是标志主观同客观相符合的哲学范畴，是人们对客观事物及其规律的正确反映，并且客观性是真理的最基本的属性。选项说法正确，但与题干无关。D项正确，真理的相对性，是指真理是具体的有条件的，即在一定条件下，人们对客观事物的发展过程及其发展规律的正确认识总是有局限的、不完全的。题干中数学家们在不同时期对三角形内角和与180度的关系提出了不同的认识，体现了真理的相对性。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-66", "q": "党的十九大报告指出：“中国特色社会主义进入新时代。”这一论断体现的哲学原理是（）。", "options": ["事物是质变与量变的统一", "“两点论”与“重点论”的统一", "矛盾是社会发展的动力", "事物是普遍联系的"], "a": 0, "e": "【A】本题考查马克思主义哲学的相关内容。A项正确，事物是质变与量变的统一，量变是质变的必要准备，质变是量变的必然结果。我国经过长期努力，尤其是改革开放以来的量变积累，才使得中国特色社会主义发生质变，引起国内主要矛盾的变化，从而进入新时代，体现了质变与量变的统一，故A项正确。B项错误，“两点论”与“重点论”的统一，坚持两点论，反对一点论；坚持重点论，反对均衡论。题干未体现，故排除。C项错误，矛盾是指事物之间或事物内部各要素之间的对立统一的关系，它对于事物的发展起推动作用，也是事物发展的动力和源泉。题干未体现，故排除。D项错误，联系是普遍的，世界上一切事物都与周围事物有着这样或那样的联系，世界是一个普遍联系的有机整体。题干未体现，故排除。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-67", "q": "“逝者如斯夫，不舍昼夜”“时乎时乎不再来”是古代哲人在启示我们：时间非常宝贵，要珍惜时间的每一分每一秒。这反映出时间具有（）的特点。", "options": ["连续性", "间隔性", "一维性", "反复性"], "a": 2, "e": "【C】本题考查哲学常识。马克思主义哲学认为，时间是指物质运动的持续性和顺序性。时间具有一维性、不可逆性。“逝者如斯夫，不舍昼夜”意思是时间就像流水一样，一去不复返；“时乎时乎不再来”是指时间失去了就不会再回来，这两句话都反映了时间一去不复返的特点，即时间的一维性。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-68", "q": "汉代王符说：“大鹏之动，非一羽之轻也；骐骥之速，非一足之力也。”下列活动未能体现这句话所蕴涵的管理思想的是：", "options": ["王所长动员单位全体人员开展技术攻关", "赵局长事必躬亲完成上级布置的工作任务", "市政府将污染治理目标分解给各职能部门", "疾控中心联合高校开展流感病毒的防治工作"], "a": 1, "e": "【B】本题考查管理学相关原理。“大鹏之动，非一羽之轻也；骐骥之速，非一足之力也”出自汉代王符《潜夫论释难》。意思是大鹏鸟直上九天，不是因为一只翅膀轻轻用劲；千里马跑得很快，不只靠一只脚的力量。形容做事情要互相支持互相合作，相辅相成，强调团队合作的重要性。A项正确，王所长动员全体人员开展技术攻关，强调了团队合作共同攻坚克难。B项错误，赵局长事必躬亲完成上级任务，亲力亲为，突出个人，忽视了团队的力量。C项正确，市政府开展污染防治把目标分解给各职能部门，体现了各部门的共同配合和努力。D项正确，疾控中心联合高校开展流感防治工作，各单位相辅相成，均发挥了作用。本题为选非题，故正确答案为B。", "tag": "政治常识"},
{"id": "pol-69", "q": "党的十九大提出“新时代我国社会主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾”，这一论断所蕴含的哲学原理是（）。", "options": ["“两点论”与“重点论”的统一", "事物发展是质变和量变的统一", "矛盾是事物发展的根本动力", "事物是普遍联系的"], "a": 0, "e": "【A】本题考查马克思主义哲学的相关内容。A项正确，“两点论”和“重点论”的统一这条方法论对应的哲学原理是事物的主次矛盾和矛盾的主次方面辩证关系原理。题干中提到的我国主要矛盾，只有一个，所以对应的原理为矛盾的主次方面辩证关系原理。其中“两点论”体现在，我们既要看到我国新时代生产力快速发展和人民生活水平显著提高的一面，又要看到我国新时代发展不平衡不充分的一面；而“重点论”体现在，我们要更加重视该矛盾的主要方面，也就是目前社会不平衡不充分的发展这一个方面。所以还要加快发展优化结构注重公平。故A项正确。B项错误，量变和质变的辩证关系，量变是质变的必要准备，质变是量变的必然结果。事物的发展是质变和量变的统一，但题干未体现此哲理。C项错误，矛盾对于事物的发展起推动作用，矛盾是事物发展的动力和源泉。题干虽然体现了矛盾，但并没有体现矛盾对于社会发展的推动作用。题干未体现此哲理。D项错误，联系的普遍性是指世界上的一切事物都处在普遍联系之中，其中没有任何一个事物孤立地存在，整个世界就是一个普遍联系的统一整体。题干未体现此哲理。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-70", "q": "我国社会主义初级阶段实行以公有制为主体、多种所有制经济共同发展的基本经济制度，促进了生产力的发展，说明实行这种制度遵循了：", "options": ["生产力决定生产关系的原理", "经济基础决定上层建筑的原理", "社会存在决定社会意识的原理", "经济制度决定生产力状况的原理"], "a": 0, "e": "【A】本题主要考查唯物史观相关内容。我国社会主义初级阶段实行以公有制为主体，多种所有制经济共同发展的基本经济制度主要是因为我国是社会主义国家，必须坚持公有制为主体，同时因为我国生产力的现实是总体水平比较低，发展不平衡，层次比较多，这就需要发展多种所有制经济来适应不同层次的生产力，推动生产力的发展，为社会主义服务。A项正确，生产力决定生产关系的性质，生产力的发展和变化，决定着生产关系的发展和变化。生产关系一定要适应生产力的状况，这是人类社会发展的普遍规律，它决定着人类社会由低级形态向高级形态的发展，一种旧的生产关系向另一种新的生产关系的过渡。我国实行以公有制为主体，多种所有制经济共同发展的基本经济制度，正是遵循了生产力决定生产关系的原理，才促进了生产力的发展。B项错误，经济基础是指由社会一定发展阶段的生产力所决定的生产关系的总和，是构成一定社会的基础；上层建筑是建立在经济基础之上的意识形态以及与其相适应的制度、组织和设施，在阶级社会主要指政治法律制度和设施。题干并未体现经济基础和上层建筑的关系。C项错误，社会存在指社会的物质生活过程，其核心是物质资料的生产方式。社会意识指社会的精神生活过程，广义指社会的一切意识要素和观念形态，包括社会心理和社会意识形式；狭义则专指关于社会关系的意识，即意识形态。题干并未体现社会存在决定社会意识的原理。D项错误，说法不正确。经济制度是一定社会占统治地位的生产关系的总和，而生产力决定生产关系。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-71", "q": "黑格尔说：“割下来的手就不是真正的人手了。”这句话表达的哲学道理是：", "options": ["承认世界的统一性", "承认世界的本原是物质的", "否认联系的形而上学观点", "承认普遍联系的辩证法观点"], "a": 3, "e": "【D】本题主要考查哲学常识。A项错误，世界是统一的，统一的基础是物质，其以具体物质形态的差异性、多样性为前提。选项表述无误，但“割下来的手就不是真正的人手”体现了整体与部分的关系，与选项联系不紧密，因此排除。B项错误，世界的本原是物质，物质的根本特性是客观实在性。选项表述无误，但题干中并没有涉及到这一观点，因此排除。C项错误，“割下来的手就不是真正的人手了”意为手离开了身体就不再具备原来的功能，不能割裂整体与部分的关系，即体现了联系的系统性原理，属于辩证法的观点。D项正确，整体与部分是相互联系的，整体是由部分构成，离开了部分，整体就不复存在；部分是整体的部分，离开了整体，部分就不能成为部分。“割下来的手就不是真正的人手了”体现了普遍联系的辩证法观点。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-72", "q": "“没有革命的理论，就没有革命的行动。”这句话说明的哲学道理是：", "options": ["理论高于实践活动", "科学理论对实践有指导作用", "理论是革命工作的出发点", "理论对实践起决定作用"], "a": 1, "e": "【B】本题主要考查理论与实践的关系。A项错误，实践是认识的来源，为认识的产生提出了需要，而认识对实践具有能动的反作用，“理论高于实践活动”本身说法是错误的。B项正确，“没有革命的理论，就没有革命的行动”说明认识能够反映实践，同时也能够指导实践，正确的认识能够积极的推动实践的发展，因此科学理论对实践具有指导作用。C项错误，实践是认识的起点，也是认识的归宿，是全部认识的基础。“理论是革命工作的出发点”本身说法不正确。D项错误，实践是认识发展的动力，是检验认识是否具有真理性的唯一标准，因此“理论对实践起决定作用”表述不正确。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-73", "q": "主张“世界上除了运动着的物质之外，什么也没有”的观点是：", "options": ["否认人的意识存在的自然唯物主义", "主张世界统一于物质的辩证唯物主义", "否认时间与空间存在性的唯心主义", "把人的意识理解为某种特殊的“精细物质”的机械唯物主义"], "a": 1, "e": "【B】本题主要考查哲学常识。“世界上除了运动着的物质之外，什么也没有”意为世界是由运动着的物质构成，世界是物质的，而物质又是运动的，世界上所有的物质都在以各种不同的方式运动，除此以外，再无其他。A项错误，题干中只提到运动与物质的关系，并没有涉及到意识。B项正确，世界上的一切事物和现象，都是物质的种种表现形态，世界的本质是物质的，题干属于主张世界统一于物质的辩证唯物主义。C项错误，唯心主义主张精神、意识第一性，物质第二性，即物质依赖意识而存在，题干中并未涉及到。D项错误，机械唯物主义用机械的力学解释一切，认为一切物质的运动都是外力推动的，割裂了物质与运动的关系，与题干不符。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-74", "q": "董仲舒认为“古之天下，亦今之天下；今之天下，亦古之天下。”这是：", "options": ["唯物论观点", "唯心论观点", "辩证法观点", "形而上学观点"], "a": 3, "e": "【D】本题主要考查哲学常识。“古之天下，亦今之天下；今之天下，亦古之天下”意为古今之天下没有什么变化，只是具有相同内涵的同一模式随时间的推移进行简单重复。其看不到事物之间的相互联系、运动、变化和发展，是在孤立地、静止地、片面地看待客观事物，属于形而上学的观点。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-75", "q": "“清明前后，种瓜点豆”，“朝霞不出门，晚霞行千里”。这些古老的谚语是我国先民通过观察时令、天气等方面的特征与生活、生产之间的联系而形成的知识体系，至今对人们的生产和生活还有重要影响。这说明：①实践活动是人们获得对具体事物认识的来源②意识对人们改造客观世界活动起指导作用③意识的主动创造性使得人能认识和发展规律④人们能够根据事物固有联系建立新的联系", "options": ["①②", "②③", "①③", "②④"], "a": 0, "e": "【A】本题主要考查哲学有关知识。古老的谚语是我国先民通过具体的生产实践，在经过认真的观察之后归纳总结的规律。①正确，“清明前后，种瓜点豆”，“朝霞不出门，晚霞行千里”。这些谚语是我国先民通过观察时令、天气等实践活动从而得出的认识。体现了实践活动是人们获得对具体事物认识的来源。②正确，先民通过观察时令、天气等特征形成了一套知识体系，至今对人民的生产和生活还有重要影响。知识体系属于意识的范畴，通过这种意识可以指导今天的生产和生活，故体现了意识对人们改造客观世界活动起指导作用。③错误，意识的主动创造性是指,我们在认识客观事物时会主动创造出一些现实不能直接感觉到的认识，比如人们会追溯过去，推测未来。其实就是创造性思维和创新意识的体现。题干中人们对生产生活过程中的联系和特征的把握没有体现意识的主动创造性。④错误，人们能够根据固有联系建立新的联系，选项本身表述没有问题，但是题干中并没有涉及到。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-76", "q": "积极者说，人生犹如一首歌，有低音也有高调，抑扬顿挫是人生美妙的旋律；消极者说，人生犹如一场戏，有高潮也有低潮，喜怒哀乐是人生无奈的节奏。这段话反映的哲理是：", "options": ["人们对事物的反映具有主体性特点", "受知识水平制约,认识具有反复性", "正确的认识产生于激烈的争论之中", "人们不可能形成对事物的一致看法"], "a": 0, "e": "【A】A项正确：对于人生有起有落这件事，积极者和消极者有不同的认识，这说明人们对事物的认识是从主观感受出发的，具有主体性特点。B项错误：认识过程的反复性是指人们对于一个复杂事物的认识往往要经过由感性认识到理性认识、再由理性认识到实践的多次反复才能完成。而题干中说的是人们对同一件事情的不同认识，不涉及认识的反复性。C项错误：题干中讲的是人们对同一件事物的不同认识，这是人从自身出发的主观认识，不涉及认识的正确性。D项错误：由于观察的角度不同，人们对同一事物会有不同的正确反映，每个人对事物认知的标准和看法都不一样，但是在有些事物上，人们通过相互交流和互相学习，可能达成一致看法，例如科学界的某些公理。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-77", "q": "习近平总书记指出，问题是事物矛盾的表现形式，我们强调增强问题意识，坚持问题导向。这句话的哲学依据是：", "options": ["具体问题具体分析是认识和解决问题的关键", "承认矛盾的普遍性是认识和解决问题的关键", "坚持问题导向才能体现中国共产党的宗旨", "问题意识是中国特色社会主义的理论基础"], "a": 1, "e": "【B】B项正确：习近平总书记在中央政治局第二十次集体学习时强调，要学习掌握事物矛盾运动的基本原理，不断强化问题意识，积极面对和化解前进中遇到的矛盾。问题是事物矛盾的表现形式，我们强调增强问题意识、坚持问题导向，就是承认矛盾的普遍性、客观性，就是要善于把认识和化解矛盾作为打开工作局面的突破口。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-78", "q": "翻开古代诗词，你可以一一品味诗人们深切的思想感情。读王维、孟浩然，你懂得了什么是钟情山水；读杜甫、白居易，你懂得了什么是忧民情结；读辛弃疾、陆游，你懂得了什么是爱国情怀，这段话体现的哲理是：", "options": ["不同事物有不同的矛盾", "矛盾的普遍性和特殊性相互转化", "同一矛盾的两个不同方面各有特殊性", "同一事物在发展的不同阶段上有不同的矛盾"], "a": 0, "e": "【A】王维、孟浩然都是唐代山水田园派的诗人，他们以山水等自然景观为主要描写对象，歌咏田园生活。杜甫是唐代现实主义诗人，心系苍生，胸怀国事。白居易创作了大量反映民生疾苦的讽喻诗。辛弃疾，南宋词人，命运多舛，但恢复中原的爱国信念始终没有动摇。陆游，南宋文学家、爱国诗人，其诗饱含爱国热情对后世影响深远。这些诗人所处的社会环境不同，思想意识不同，创作角度不同，因而创作出的诗作不同，体现了不同事物有不同的矛盾。A项符合题意。B、C、D项的哲理题干中没有体现。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-79", "q": "达尔文观察到，养猫越多的地方，羊也可以养的越多，原因在于“猫一田鼠一花蜂一三叶草一羊”之间存在着生物食物链。这体现的哲学原理是：", "options": ["矛盾具有普遍性和客观性，矛盾是事物发展的源泉和动力", "联系具有普遍性和多样性，任何事物都处在普遍联系之中", "真理具有绝对性和相对性，绝对真理包含在相对真理之中", "认识具有反复性和无限性，认识是一个辩证运动的过程"], "a": 1, "e": "【B】B项符合题意：生物食物链是指各种生物通过一系列吃与被吃的关系(捕食关系)彼此联系起来的序列，这正体现了马克思主义哲学中联系的观点。联系的观点是唯物辩证法的一个总特征，所谓联系就是事物之间以及事物内部诸要素之间的相互影响、相互制约和相互作用的关系，而“猫-田鼠-花蜂-三叶草-羊”就是一个由于生物之间的捕食关系而彼此联系起来的生物食物链。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-80", "q": "党员的党龄从何时开始计算：", "options": ["支部大会通过其为预备党员之日起", "支部大会通过其为正式党员之日起", "党的基层委员会通过其为预备党员之日起", "党的基层委员会通过其为正式党员之日起"], "a": 1, "e": "【B】B项正确，《中国共产党章程》第七条第四款规定：“预备党员的预备期，从支部大会通过他为预备党员之日算起。党员的党龄，从预备期满转为正式党员之日算起。”故正确答案为B。", "tag": "政治常识"},
{"id": "pol-81", "q": "我们纪念红军长征胜利80 周年，就是要缅怀革命先烈不朽功勋，继承光荣的革命传统，张扬伟大的长征精神，走好自己的长征路。这主要是因为：", "options": ["量变能引起质变", "意识对物质具有反作用", "外因是事物发展的基本条件", "世界是普遍联系的"], "a": 1, "e": "【B】B项正确：长征精神，是正确反映客观事物及其发展规律的意识，能够指导我们有效的开展实践活动，促进客观事物的发展，对我们走好自己的长征路具有积极的指导意义，正体现了意识的反作用。A项错误：题干强调的是“长征精神”这一意识，属于唯物观的内容；“量变引起质变”属于辩证法相关内容，不符合题意。C项错误：题干强调的是“长征精神”这一意识，属于唯物观的内容；“内外因”属于辩证法相关内容，不符合题意。D项错误：题干强调的是“长征精神”这一意识，属于唯物观的内容；“联系”属于辩证法相关内容，不符合题意。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-82", "q": "习近平主席在谈到如何提高工作效率时说：“必须学会运用辩证法，分清层次，认真思考，‘审大小而图之，酌缓急而布之，连上下而通之，衡内外而施之。’”此处用典不包含的哲理是：", "options": ["坚持“两点论”和“重点论”的统一", "以联系的观点和发展的观点看待问题", "尊重客观规律基础上发挥主观能动性", "遵循社会发展前进性与曲折性的统一"], "a": 3, "e": "【D】本题考查马克思主义哲学原理的具体运用，请注意题目问的是用典不包含的哲理，意为不包含哲学原理。A项包含，用典中的大小、缓急等等均体现出两点论和重点论的统一。B项包含，用典中的审大小而图，酌缓急而布等就是从发展的眼光来看，做最重要的事情。C项包含，用典中的图之、布之、通之、施之均可以体现在把握规律的前提下发挥主观能动性去做。D项不包含，因为题干中的典故没有体现事物的反复或者倒退，没有体现曲折性。本题为选非题，故正确答案为D。（注：本题有部分人认为选C，理由是C中的规律不是辩证法的内容，而其他三项是，这是对题目的曲解，题目问的是哲理，即哲学原理，也就是全部的哲学原理，而非仅仅指的辩证法原理。）", "tag": "政治常识"},
{"id": "pol-83", "q": "数学中常常能折射出人生智慧。下列选项与算式体现的道理一致的是：", "options": ["江碧鸟逾白，山青花欲燃", "问渠那得清如许？为有源头活水来", "聚沙成塔，集腋成裘", "横看成岭侧成峰，远近高低各不同"], "a": 2, "e": "【C】C项正确：题干中的算式主要想表达量变和质变的关系，强调量的积累导致质的改变。“聚沙成塔，集腋成裘”的意思是通过积累“沙”可以建成“塔”，通过集聚“腋”可以织成“裘”，同样强调了量变引起质变原理；A项错误：该句出自杜甫《绝句江碧鸟逾白》，意为：江水碧波浩荡，衬托水鸟雪白羽毛，山峦郁郁苍苍，红花相映，便要燃烧。并没有体现量变与质变的关系；B项错误：该句出自朱熹《观书有感其一》，意为：渠中的水这么清是什么原因呢？是因为有源头活水不断进行补充。体现了与时俱进的哲学思想；D项错误：该句出自苏轼《题西林壁》，意为：从正面看庐山山岭连绵起伏，从其他面看庐山山峰耸立，从远处、近处、高处、低处各个不同的角度看庐山，庐山都呈现出各种不同的样子。蕴含着看问题要全面的哲学思想。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-84", "q": "成功就是把“不可能”变成“不！可能”，把“Impossible”变成“I'mpossible”。这一说法的合理性在于：", "options": ["思维和存在具有同一性", "实践具有直接现实性", "真理具有条件性", "意识具有主动创造性"], "a": 1, "e": "【B】B项正确：把“不可能”变成“不！可能”，把“Impossible”变成“I'mpossible”需要通过实践去实现。实践的直接现实性是指实践是一种直接现实性活动,它可以把人们头脑中的观念的存在变为现实的存在，符合题干的表述。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-85", "q": "鲁迅先生曾说，贾府里的焦大是不会爱上林妹妹的。这句话蕴含的哲学意义是：", "options": ["社会存在决定社会意识", "经济基础决定上层建筑", "社会意识具有主观能动性", "社会意识对社会存在具有反作用"], "a": 0, "e": "【A】A项正确：鲁迅先生的这句话反映了不同的人具有不同的审美观、世界观和爱情观。在《红楼梦》中，焦大是贾府里的一个老家奴，是处于当时社会最底层的劳动人民，林妹妹则是贾母的嫡亲外孙女，两人的社会阶级悬殊。以焦大的经济能力和社会地位，他无法领会林妹妹的精神世界，两人的价值观和思维方式是截然不同的。焦大的社会存在决定了他特有的价值观，即社会存在决定社会意识；B项错误：焦大不会爱上林妹妹，不仅跟经济基础有关，还跟他的社会阶级地位有关。他处于社会底层，经济能力必然薄弱；C、D项错误：社会意识具有能动性是指社会意识对社会存在的反作用，先进的社会意识对社会存在发展起积极的推动作用，落后的或反动的社会意识对社会存在发展起阻碍作用，与题干无关。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-86", "q": "习近平总书记在中央政治局第二十次集体学习时强调，要增强问题意识，坚持问题导向。这体现的哲学原理是：", "options": ["矛盾具有普遍性和客观性，矛盾是事物发展的源泉和动力", "联系具有普遍性和多样性，任何事物都处在普遍联系之中", "真理具有绝对性和相对性，绝对真理包含在相对真理之中", "认识具有反复性和无限性，认识是一个辩证运动的过程"], "a": 0, "e": "【A】A项正确：中共中央政治局于2015年1月23日就辩证唯物主义基本原理和方法论进行第二十次集体学习。习近平总书记强调：“要学习掌握事物矛盾运动的基本原理，不断强化问题意识，积极面对和化解前进中遇到的矛盾。问题是事物矛盾的表现形式，我们强调增强问题意识、坚持问题导向，就是承认矛盾的普遍性、客观性，就是要善于把认识和化解矛盾作为打开工作局面的突破口。”增强问题意识，坚持问题导向，就是承认矛盾的普遍性和客观性；认识矛盾，进而解决矛盾，推动事物的发展，这说明矛盾是事物发展的源泉和动力。B、C、D项错误：题干中的“问题意识”和“问题导向”没有体现选项中涉及的联系、真理和认识的基本原理。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-87", "q": "下列选项中两组成语蕴含哲理相同的是：", "options": ["流水不腐，户枢不蠹—人无远虑，必有近忧", "奢靡之始，危亡之渐—千里之堤，溃于蚁穴", "生于忧患，死于安乐—城门失火，殃及池鱼", "螳螂捕蝉，黄雀在后—尺有所短，寸有所长"], "a": 1, "e": "【B】A项错误：“流水不腐，户枢不蠹”意指常流的水不发臭，常转的门轴不遭虫蛀，比喻经常运动，生命力才能持久，才会有旺盛的活力，蕴含运动是物质的根本属性和存在方式的哲学道理。“人无远虑，必有近忧”意指没有长远的打算，那么近期的事情就会多有忧虑，蕴含矛盾是对立统一的哲理。两者蕴含的哲理不同；B项正确：“奢靡之始，危亡之渐”意指奢靡行为开始之时，也是危亡渐渐来临之际。“千里之堤，溃于蚁穴”意指千里长的大堤，往往因蚂蚁洞穴而崩溃，比喻小事不慎将酿成大祸。两者都是说明量的积累可以引起质的变化，反映了量变与质变的关系；C项错误：“生于忧患，死于安乐”意指忧愁患害使人谋求生存，而安逸享乐使人萎靡死亡，蕴含矛盾双方相互转化的哲学道理。“城门失火，殃及池鱼”指城门失火，大家都到护城河取水，水用完了，鱼也死了，蕴含物质世界存在着普遍联系的哲学道理。两者蕴含的哲理不同；D项错误：“螳螂捕蝉，黄雀在后”指螳螂正要捉蝉，不知黄雀在它后面正要吃它，蕴含联系具有普遍性的哲学道理。“尺有所短，寸有所长”比喻人或事物各有其长处和短处，蕴含要坚持用两分法，全面地看问题，反对一点论的哲学道理。两者蕴含的哲理不同。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-88", "q": "）。", "options": ["社会政治", "社会经济", "精神文化", "意识形态"], "a": 1, "e": "【B】题干中设问为首要因素，意味着在四个选项中要选择最基本、最直接、影响最大最深远的。根据马克思历史唯物到诸多因素的影响，其中最根本的还是生产力和生产关系、经济基础和上层建筑之间的关系。比较ABCD四个选项，最符合上述表述的是B项，经济基础决定上层建筑，比如社会经济的发展到了资本主义雇佣的时期，那势必会影响人民去改革现有的政治体制，以适应新的资本主义的经济体制。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-89", "q": "改革开放是一场深刻而全面的社会变革，每一项改革都会对其他改革产生重要影响，每一项改革又都需要其他改革协同配合，要更加注重各项改革的相互促进、良性互动，整体推进，重点突破，形成推进改革开放的强大合力。这段话体现的哲学原理是（）。", "options": ["矛盾是同一性和斗争性的统一", "事物是普遍联系的", "事物的发展是前进性和曲折性的统一", "矛盾是社会发展的动力"], "a": 1, "e": "【B】题目中体现的是每一项改革都会对其他改革产生重要影响，每一项改革又需要其他改革协同配合。所以体现的是事物之间的普遍联系。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-90", "q": "国产动画电影《西游记之大圣归来》，从古典名著《西游记》中汲取灵感，凭借优良的制作技术和丰富的视觉效果，塑造了与传统《西游记》完全不同的全新人物形象，它昭示了一条将传统与现代有机结合的国产动画电影发展道路，是一部符合“互联网+”时代要求，整合中国与国外动画资源，具备世界眼光的影片。其创作过程体现的哲学道理是（）。", "options": ["事物质变是量变的必然结果", "对规律的认识与改造是其成功的源泉", "创造性思维是其成功的源泉", "辩证的否定是事物发展和联系的环节"], "a": 3, "e": "【D】A项错误，此项说法正确，但是题干没有体现量变与质变之间的关系。B项错误，“改造规律”说法错误，规律是客观的，不以人的意识为转移，人可以认识规律、掌握规律、运用规律。C项错误，创造性属于成功的因素之一，但并不是成功的源泉，因此选项表述错误。D项正确，辩证否定的实质是扬弃，即既克服又保留。《西游记之大圣归来》从古典名著《西游记》中吸取了灵感，这体现了辩证否定的“保留”，但《西游记之大圣归来》克服传统的人物，塑造了全新人物形象，这体现了辩证否定的“克服”。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-91", "q": "孟子曰：“夫物之不齐，物之情也。或相倍蓰，或相什百，或相千万。子比而同之，是乱天下也。”其哲学寓意是：", "options": ["事物之间或事物内部普遍存在矛盾", "矛盾双方在一定条件下可相互转化", "内部矛盾总是事物发展的根本动力", "矛盾着的事物及每个侧面各有特点"], "a": 3, "e": "【D】题干语句出自《孟子滕文公上》，大意是天下万物各不相同，这是客观情形。该句强调了事物的差异性，从哲学角度来说，体现的是矛盾特殊性原理，即矛盾着的事物及其每一个侧面各有其特点。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-92", "q": "调查研究发现，由于原料、人工等成本大幅攀升，很多农产品的价格上涨是成本推动型的，还有些是周期性的。这种通过调查研究得出结论的做法符合：", "options": ["一切从实际出发，实事求是的要求", "用发展的观点看问题的要求", "两点论和重点论相统一的要求", "唯物主义的方法论要求"], "a": 0, "e": "【A】题干“通过调查研究得出结论”体现的正是从实际出发，尊重客观事实，符合“一切从实际出发，实事求是”的要求。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-93", "q": "全国两会开幕前，人大代表、政协委员们为了提交议案、提案，会对经济社会发展问题进行深入的调查研究。这体现的哲理是：", "options": ["主观与客观具体的历史的统一", "具体问题具体分析", "科学理论对实践具有指导作用", "意识是人脑对客观事物的正确反映"], "a": 0, "e": "【A】A项正确，主观与客观具体的历史的统一是指：主观要符合客观，想问题、办事情要坚持一切从实际出发。题干中人大代表、政协委员们为提议案，对经济社会发展问题进行深入的调查研究，正是坚持从实际出发，实事求是，做到主观与客观的具体的历史的统一，当选。B项错误，具体问题具体分析是要求人们在做事情、想问题时，要根据事情的不同情况采取不同措施，不能一概而论，与题意不符，排除。C项错误，此项中的“科学理论”，题干中并未提及，排除。D项错误，此项中的“正确反映”无法从题干中得出，议案、提案也并非是全部正确的，排除。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-94", "q": "作家肖伯纳说“人生有两大悲剧，一是没得到你心爱的东西，另一是得到了你心爱的东西”；学者周国平则说“人生有两大快乐，一是没有得到你心爱的东西，于是你可以去寻求和创造，另一是得到了你心爱的东西，于是你可去品味和体验”。从哲学角度看，两个观点存在差异的主要原因是：", "options": ["追求真理是一个永无止境的认识过程", "价值判断和价值选择具有社会历史性特征", "人们的认识结果是由客体对主体的作用决定的", "意识对于客观事物的反映是主动的、有选择的"], "a": 3, "e": "【D】意识活动具有主动创造性和自觉选择性。意识对客观世界的反映是主动的、有选择的，并不是客观世界有什么就反映什么，只有当人们的实践活动需要时，人们才会去主动地反映它。从哲学角度来看，肖伯纳和周国平观点不同的主要原因是意识活动具有主动创造性和自觉选择性。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-95", "q": "有人把做学问比作勘探石油，钻井打到3000 米找不到油，就打到5000 米、8000 米······只要找准地方，越往下打，希望就越大。学懂党的理论和打井一样没有捷径，唯有深入学、刻苦学、持久学，才能掌握其精神实质。这段话蕴含的哲理是", "options": ["量变是质变的必要准备", "要善于抓事物的主要矛盾", "质变和量变会相互转化", "要善于发挥意识能动作用"], "a": 0, "e": "【A】本题考查政治常识。有人把做学问比作勘探石油，钻井打到3000米找不到油，就打到5000米、8000米只要找准地方，越往深处打，希望就越大。这个形象比喻，对于党员、干部学习党的十九大精神颇有启发，这也表明任何事物的发展都必须首先从量变开始，没有一定程度的量的积累，就不可能有事物性质的变化，就不可能实现事物的飞跃和发展。A项正确，题干描述的情况就是体现了量变是质变的必要准备。B项错误，马克思主义告诉我们，在诸多矛盾中，要善于抓主要矛盾，在主要矛盾中要善于抓矛盾的主要方面。题干中没有体现。C项错误，量变是事物发展的一个过程，质变是量变发展到一定阶段时的突变，量变是质变的准备阶段，质变是量变的新起点。题干中主要讲的是量变引起质变。D项错误，意识能动作用指人的主观意识和实践活动对于客观世界的能动作用。题干中没有提到意识能动作用。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-96", "q": "随着医疗产业的发展，医疗领域的人工智能也越来越先进，可以开展健康检测、快速诊断疾病、做手术等。如今，人工智能早已不再是科幻小说中的专有名词，它已经突破了从“不能用”“不好用”到“可以用”的技术拐点，进入了快速发展时期。这反映的哲学原理是", "options": ["意识是人脑所特有的机能", "意识活动具有主体选择性", "人类的认识活动有反复性", "实践是认识的来源和动力"], "a": 3, "e": "【D】本题考查政治常识。A项错误，人脑是高度发达的物质基础，是意识活动的物质器官。人脑结构的复杂性和组织的严密性，决定了它具有产生意识的生理基础。意识是人脑的机能。选项本身表述正确，但题干并非直接反映意识和人脑之间的关系。B项错误，意识活动具有主动创造性和自觉选择性。意识对客观世界的反映是主动的、有选择的，并不是客观世界有什么就反映什么。题干强调人工智能的不断发展，没有体现出意识选择性的反映客观世界。C项错误，认识具有反复性。人们对一个事物的正确认识往往要经过从实践到认识、再从认识到实践的多次反复才能完成。题干更强调人工智能的不断发展，而不是对其认识的不断反复。D项正确，实践是认识的来源。认识是主体对客体的能动的反映，这种反映只有在实践中、在主体和客体的相互作用中才能完成。实践是认识发展的动力。认识产生于实践的需要，人们在实践中不断遇到的新问题、产生的新要求，推动着人们去进行新的探索和研究。随着医疗产业的发展，医疗领域的人工智能也越来越先进，说明随着实践的发展，认识也在不断发展，体现了实践是认识的来源和动力。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-97", "q": "近年来，我国科技体制改革全面发力、多点突破、纵深发展，在重要领域和关键环节取得实质性突破。从“天眼”探空到“蛟龙”探海，从神舟飞天到高铁奔驰，一系列重大科技创新成果彰显了改革带来的蓬勃创新活力。这表明创新", "options": ["是社会发展和变革的先导", "决定人类思维方式的变革", "是生产力发展的根本动力", "推动了社会生产力的发展"], "a": 3, "e": "【D】本题考查政治常识。A项错误，实践基础上的理论创新是社会发展和变革的先导，而本题中单独讲“创新”是社会发展和变革的先导，表述错误。B项错误，本身表述错误，创新推动人类思维方式的变革，但不决定。C项错误，本身表述错误，生产力发展的根本动力是两对矛盾：生产力和生产关系之间的矛盾、经济基础和上层建筑之间的矛盾。D项正确，题干中“一系列重大科技创新成果”取得实质性突破，带来了创新活力，推动了社会生产力。体现了创新推动社会生产力的发展。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-98", "q": "下列名句与所体现的哲学原理对应错误的是:", "options": ["士别三日，当刮目相看——事物是发展变化的", "流水不腐，户枢不蠹——运动是物质的根本属性", "唇齿相依，唇亡齿寒——事物是普遍联系的", "不识庐山真面目，只缘身在此山中——真理是具体且多元的"], "a": 3, "e": "【D】本题主要考查哲学常识。A项正确，“士别三日，当刮目相看”指分别一段时间，别人已有进步，当另眼相看。说明在分别的时间内，人发生了可喜的变化，体现了事物是不断发展前进的。B项正确，“流水不腐，户枢不蠹”指常流的水不发臭，常转的门轴不遭虫蛀；比喻经常运动，生命力才能持久，才有旺盛的活力。说明物质只有在运动中才能存在，运动是物质的存在方式和根本属性。C项正确，“唇齿相依，唇亡齿寒”比喻双方关系极为密切，休戚相关，体现了事物之间相互连结、相互依赖、相互影响的关系，表明事物是普遍联系的。D项错误，“不识庐山真面目，只缘身在此山中”意为处于庐山之中不能认识庐山真实的面目，是因为看得不全面，克服主观片面性才能获得对事物的正确认识，体现的是整体观这一哲学原理。真理是多元的本身表述错误，且选项并未体现。马克思主义的真理论认为，真理的客观来源只有一个，即物质世界。凡与客观对象相符合一致的认识就是真理，否则就不是真理，因此真理不能是多元的。本题为选非题，故正确答案为D。", "tag": "政治常识"},
{"id": "pol-99", "q": "新西兰一家园艺研究所研究发现，水果成熟时会释放挥发性的化合物，而且随着成熟程度的增加，其浓度也会有所变化。研究人员正是根据水果这一特性，制成了一种能“感知”水果是否成熟的标签。当水果成熟时，标签通过感知其释放的挥发性化合物的浓度而变换颜色。这段话体现的哲理是：", "options": ["意识是人脑的机能和属性", "意识对人们改造世界具有指导作用", "意识活动具有科学预见性", "意识活动具有直接现实性"], "a": 1, "e": "【B】本题考查哲学常识，主要涉及辩证唯物主义的相关内容。A项错误，意识是人脑的机能，但不是人脑的属性。意识是人脑特有的机能，人脑是产生意识的物质器官。人脑是物质，物质的根本属性是运动，故该选项表述错误；B项正确，题干描述的“水果这一特性”属于自然规律，人们认识并利用这一自然规律制造出了“感知标签”，体现了意识可以能动的改造世界，对人们改造世界的活动具有指导作用；C项错误，意识活动具有正确和错误之分，只有正确的意识才具有科学预见性。正确的意识是指如实地反映客观事物的本来面目（包括状态、性质、变化规律等）的意识。正确意识的这一性质决定了它能够对事物的发展趋势作出正确的分析、判断和预测，使人们采取正确的措施，从而推动事物的发展。错误的意识歪曲了事物的本质，会阻碍事物的发展；D项错误，意识具有目的性、创造性和计划性，但不具有直接现实性。实践活动具有直接现实性。故正确答案是B。", "tag": "政治常识"},
{"id": "pol-100", "q": "下列观点体现了朴素唯物主义思想的是（）。", "options": ["凡是存在的都是合理的", "天地合气，万物自生", "没有调查就没有发言权", "祸兮福之所倚，福兮祸之所伏"], "a": 1, "e": ".【B】本题主要考查哲学有关问题。朴素唯物主义是用某种或几种具体物质形态来解释世界本原的哲学学说，其否认世界是神创造的，试图找到具有无限多样性的自然现象的统一。A项错误，黑格尔认为，宇宙的本原是绝对精神。它自在地具备着一切，然后外化出自然界、人类社会、精神科学，最后在更高的层次上回归自身。简单地说，凡是绝对精神外化出的存在的事物，都是合理地存在的，就是存在即合理。主张世界的本原是“绝对精神”，这是客观唯心主义的观点。B项正确，“天地合气，万物自生”出自东汉唯物主义思想家王充，其认为万物是由于物质性的“气”自然运动而生成的，天和地都是无意志的自然物质实体，宇宙万物的运动变化和事物的生成是自然无为的结果，属于朴素唯物主义思想。C项错误，“没有调查就没有发言权”是毛主席提出的著名论断。调查研究是从实际出发的中心一环，既是“从物到感觉和思想”的唯物主义认识路线的具体体现，也是发挥人的主观能动性把握客观规律的具体途径，属于辩证唯物主义。D项错误，“祸兮福之所倚，福兮祸之所伏”指福与祸相互依存、相互转化。祸使人悲伤，福使人快乐，但祸可能使人吸取教训而产生福，福可能使人乐极生悲而产生祸，两者是对立统一的矛盾关系，属于辩证唯物主义。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-101", "q": "古语“夫物之不齐，物之情也。或相倍蓰，或相什百，或相千万。子比而同之，是乱天下也。（《孟子·滕文公上》）”主要体现的马克思主义哲学原理是：", "options": ["事物运动、变化和发展原理", "矛盾的同一性和斗争性相互关系原理", "矛盾的普遍性原理", "矛盾的特殊性原理"], "a": 3, "e": ".【D】本题考查马克思主义哲学常识，涉及唯物辩证法相关知识，需要结合题干分析。“夫物之不齐，物之情也。或相倍蓰，或相什百，或相千万。子比而同之，是乱天下也。”齐，是指相同、相等意，如《庄子齐物论》。这句话的意思是：“世间万物不同是客观道理，他们之间相差或一倍，或百、千、万倍。你认为他们相同，是扰乱天下自然之理的。”强调物质的差异，即矛盾特殊性，可知D项正确。A项错误，世界是物质的，物质是运动的，整个世界就是永恒运动着的物质世界。哲学讲的“运动”是指一切事物的变化和过程，这种变化和过程是物质的根本属性，是物质的存在方式。题干未体现此哲学原理；B项错误，同一性和斗争性是矛盾的两种基本属性。矛盾的同一性，指矛盾双方相互依存，相互贯通，在一定条件下相互转化。矛盾的斗争性，指矛盾着的对立面之间相互排斥、相互分离的趋势。题干未体现此哲学原理；C项错误，矛盾的普遍性是指矛盾存在于一切事物中，并且贯穿于事物发展过程的始终，即矛盾无处不在，矛盾无时不有。题干强调的是万事万物各不相同，每个事物的矛盾都有不同的特点，选项与题干不相符；D项正确，矛盾的特殊性是指具体事物所包含的矛盾及每一个矛盾的各个方面都有其特点。题干提到物品千差万别，强调每个物品各有特点，体现了矛盾的特殊性原理。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-102", "q": "在生活实践中，人们会自觉不自觉地思考世界、思考周围的人和事，在思考中会触及各种具有哲学性质的问题，下列属于哲学层面的思考的是：", "options": ["劳动力是商品吗", "陶瓷是硅酸盐材料吗", "存在就是被感知吗", "水为什么往低处流"], "a": 2, "e": ".【C】抓住题目当中的关键词“属于哲学层面的思考”来解题。C项正确：“存在就是被感知”是英国哲学家贝克莱的名言，他是近代经验主义的重要代表之一，开创了主观唯心主义。“存在就是被感知吗”属于哲学层面的思考。A项错误：属于经济层面的思考。B项错误：属于科技生活层面的思考。D项错误：属于自然现象层面的思考。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-103", "q": "在任何社会中，构成社会财富的物质内容是：", "options": ["货币", "资本", "使用价值", "劳动"], "a": 2, "e": ".【C】马克思在《资本论第一卷第一章商品的两个因素》中指出：“使用价值只是在使用或消费中得到实现。不论财富的社会形式如何，使用价值总是构成财富的物质内容。在我们所要考察社会形式中，使用价值同时又是交换价值的物质承担者”。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-105", "q": "下列诗句中所蕴含的哲理不同于其他三项的是：", "options": ["人间四月芳菲尽，山寺桃花始盛开", "乱花渐欲迷人眼，浅草才能没马蹄", "深处种菱浅种稻，不深不浅种荷花", "梅须逊雪三分白，雪却输梅一段香"], "a": 1, "e": ".【B】本题考查哲学常识，主要涉及辩证法的相关知识。A项：该诗句的意思是：四月的花基本凋谢了，但是山寺桃花依然盛开。因为山上和山下地势不同，温差不同，所以同一植物生长的状况也不同，体现了矛盾具有特殊性，要求我们具体问题具体分析。B项：该诗句的意思是：眼观岸边野花，渐使游人为之着迷；路上浅浅绿草，仅能把马蹄遮盖。这两句从植物的变化写早春景象，作者通过对景色的客观描写，表达了作者流连忘返，在西湖早春风光中无比喜悦的感受，并没有体现哲学道理。C项：该诗句的意思是：在水深的地方种上菱角，水浅的地方种植水稻，在那不深不浅的水域里种上荷花。不同的植物种在不同的地方，体现了矛盾的特殊性，要求我们做任何事情都要从实际出发，因地制宜，不能形而上学地搞一刀切，绝对化。D项：该诗句的意思是：梅花须逊让雪花三分晶莹洁白，雪花却没有梅花的清香。梅香而不白，雪白而无香说明事物既有优点，也有不足，体现了矛盾普遍性与特殊性相结合的原理，告诉我们要用全面的观点看问题。A、C、D项都体现了矛盾的特殊性原理。本题为选非题，故正确答案为B。", "tag": "政治常识"},
{"id": "pol-107", "q": "农民说，幸福就是庄稼收成好，收入增加；职业经理人认为，最幸福的事情就是把公司做成一个世界品牌；教师认为，培养出优秀学生就是最幸福的事。可见，不同的人对幸福的诠释不同，这说明：", "options": ["价值判断依据事实，具有真理性", "价值判断因时而异，具有历史性", "价值判断因人而异，具有主观性", "价值判断没有规律，具有盲目性"], "a": 2, "e": ".【C】价值判断是人们对事物能否满足主体需要以及满足程度所作出的判断。因为价值判断是对事物属性与人的需要关系作出的判断，因此，价值判断既具有客观性又具有主观性。题干中，不同职业的人，对幸福有着不同的诠释，体现的正是价值判断的主观性。C项分析正确，A、B、D三项表述不符合题意。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-109", "q": "古诗云：“眼处心生句自神，暗中摸索总非真。画图临出秦川景，亲到长安有几人?”下列选项中与此诗所蕴含的哲理相同的是：", "options": ["近水楼台先得月，向阳花木易为春", "竹外桃花三两枝，春江水暖鸭先知", "纸上得来终觉浅，绝知此事要躬行", "日出江花红胜火，春来江水绿如蓝"], "a": 2, "e": ".【C】题干诗句出自元好问《论诗三十首》中的第十一首，强调诗要抒写诗人的亲身真实感受，只在心中暗中摸索，临摹前人作品，就想画出秦川长安的真实图景是不可能的。其中蕴含的哲学原理是实践是认识的来源，实践决定认识。四个选项中，C项同样强调实践对认识的决定作用，A、B、D项均不符合题意。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-110", "q": "下列各句与“塞翁失马，焉知非福”蕴含哲理相同的是：", "options": ["尺有所短，寸有所长", "乐极生悲，否极泰来", "千里之行，始于足下", "动中有静，静中有动"], "a": 1, "e": ".【B】“塞翁失马，焉知非福”说的是在一定的条件下，矛盾双方会相互转化。四个选项中只有“乐极生悲，否极泰来”体现了这一观点；A、C、D三项错误，B项正确。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-111", "q": "古诗云：“眼处心声句自神，暗中摸索总非真。画图临出秦川景，亲到长安有几人？”下列选项中与此诗所蕴含的哲理相同的是（）。", "options": ["纸上得来终觉浅，绝知此事要躬行", "竹外桃花三两枝，春江水暖鸭先知", "近水楼台先得月，向阳花木易为春", "日出江花红胜火，春来江水绿如蓝"], "a": 0, "e": ".【A】题干诗句出自元好问《论诗三十首》中的第十一首，强调诗要抒写诗人的亲身真实感受，只在心中暗中摸索，临摹前人作品，就想画出秦川长安的真实图景是不可能的。其中蕴含的哲学原理是实践是认识的来源，实践决定认识。四个选项中，A项同样强调实践对认识的决定作用，B、C、D项均不符合题意。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-112", "q": "最近，“鬼魂探测器”手机软件十分流行，据称可以探测出“鬼魂”，小高安装了这款软件，探测时手机上出现了“鬼魂”的轮廓并伴有恐怖的声音，小高吓得一夜没睡。后软件开发者说，这只是个娱乐程序，“鬼魂”形象是事先安装在软件中的。这件事说明（）。", "options": ["“鬼魂”是客观存在的，不受主观认识的影响", "“鬼魂”并不存在，但可以创造出来", "所谓的“鬼魂”只不过是植入人脑中的观念性的东西", "人脑对“鬼魂”是根本不可认识的"], "a": 2, "e": ".【C】A项错误，按唯物论的说法，“鬼魂”不是客观存在的，它受主观认识的影响；B项错误，“鬼魂”不是客观存在的，而只是人的主观意识；C项正确，鬼魂是不存在的东西，也不可能被创造出一种客观存在，意识是物质在人脑中的反映；D项错误，人脑可以对客观事物产生认识，但是认识的结果可能正确也可能不正确。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-113", "q": "面对激烈的竞争，一些成功企业的生存之道是：拿出更好的产品来击败自己的原有产品。有人将这种行为戏称为“自吃幼崽”。这体现的哲理是（）。", "options": ["追求真理是无限和反复的过程", "事物自身的矛盾具有不平等性", "事物的否定性是对自身的否定", "事物发展是一个由量变到质变的过程"], "a": 2, "e": ".【C】作为辩证法三大规律之一的否定之否定规律，它在辩证法发展史上经历的过程恰恰与这一规律的本质完全吻合，真正体现出了“言行一致、表里如一”的特点。换句话说，在哲学史上否定之否定规律自身发展过程的特点就是否定之否定。具体说来，整个发展过程经历了肯定、否定、否定之否定（肯定）的过程，这一特点与否定之否定规律自身具有的规定性恰好保持了一致性。题中所说完全符合否定之否定的含义。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-114", "q": "用一杯水救一车着了火的柴禾而无济于事，谓之杯水车薪。如今在一些地方，通过新技术，只需一瓶矿泉水的水量，就能使一辆汽车洁净如新，不妨称之为“杯水车新”。“杯水车新”说明（）。（1）事物之间都存在着满足人们现实需要的客观联系（2）人们根据自身需要，必然能建立起事物间的新的具体的联系（3）事物的人为联系是在主客观条件相互作用下形成的（4）世界并不缺乏联系，缺乏的是善于发现联系的创新意识", "options": ["（1）（4）", "（2）（3）", "（1）（2）", "（3）（4）"], "a": 3, "e": ".【D】（1）错误，“事物之间都存在着满足人们现实需要的客观联系”，表达过于主观；（2）错误，“人们根据自身需要，必然能建立起事物间的新的具体的联系”，表达不准确，联系不是人们自己主观建立的，需要客观现实条件；（3）正确，“事物的人为联系是在主客观条件相互作用下形成的”，说法正确，事物的人为联系是主观与客观的辩证统一，主观的需要加上客观的实践；（4）正确，“世界并不缺乏联系，缺乏的是善于发现联系的创新意识”，说法正确，体现了联系的普遍性和人的主观能动性。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-115", "q": "美国著名影星布拉德皮特主演的电影《返老还童》，描述的是主人公本杰明巴顿一出生便如80 岁老人一般，之后便越活越年轻，最后竟以婴儿的形态离开人世。但现实中，古今中外，从没有真正出现这一现象，这是因为：", "options": ["人类还没有找到可以“返老还童”的神奇干细胞", "人类现有的医学、生理学技术手段还不可能实现“返老还童”", "“生-弱-壮-衰-亡”是事物发展不可违背的客观规律", "人类还没有真正找到“穿越”时空的技术手段"], "a": 2, "e": ".【C】客观性是规律的根本特点，它的存在不依赖于人的意识。相反，人的意识及其指导下的实践却要受规律的支配。不管人们是否认识到，承认不承认，规律都客观存在着，并以一定的方式起作用。规律的客观性表明，人们不能藐视规律，更不能创造和消灭规律。人在客观规律面前又不是完全消极被动无所作为的。人们在实践中可以认识或发现规律，并利用这种合规律的认识指导实践，达到改造世界、为人类谋利的目的。人们还可以改变规律发生作用的条件和形式，使事物朝着有利于人类的方向发展。“穿越”和“返老还童”都是影视剧中的桥段，在现实世界中没有科学依据，事物发展是有其客观规律性的。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-117", "q": "“面子”一词有着浓厚的东方文化色彩，囊括了人的地位、财富、尊严、人格等内涵，是人们进行社交活动的外观表征，代表着他人、社会对自身的综合评价。尽管时代发生了很大的变化，但人们重“面子”的观念依旧存在。这说明：", "options": ["社会存在决定社会意识", "物质是运动的，同时又是相对静止的", "意识是物质的主观映像", "社会意识具有相对独立性"], "a": 3, "e": ".【D】“尽管时代发生了很大的变化，但人们重‘面子’的观念依旧存在”，这句话是解题的突破口。“面子”的观念作为一种社会意识，它虽然随着社会存在的变化而变化，但社会意识具有相对独立性，和社会存在的变化并不是完全同步的。题干描述时代在变化，而人们的“面子”观念依旧存在的现象，正是社会存在和社会意识发展的不平衡，社会意识具有相对独立性的特点，D项符合题干中心意思，当选。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-118", "q": "“天下虽安，忘战必危”是我国古代著名的军事思想，充满着朴素的辩证法智慧。下列体现的哲学思想与这句话相同的是：", "options": ["不谋全局者不足以谋一域", "有心栽花花不开，无心插柳柳成荫", "贾人旱则资舟，水则资车，以待乏也", "富贵而恣势弄权，乃自取灭亡之道"], "a": 2, "e": ".【C】“天下虽安，忘战必危”指国虽大，好战必亡，天下虽平，忘记了战备就一定会产生危机。体现了我国古代的一种朴素的辩证法的哲学思维。C项“贾人旱则资舟，水则资车，以待乏也”意思是商人旱天购买舟船，涝天购买车辆，等待缺乏（等待货有所缺，伺机卖出）。与之是同样的道理。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-119", "q": "下列论述符合马克思主义哲学观点的是（）", "options": ["意识是一种特殊的物质", "人有多大胆，地有多大产", "时间和空间是物质的根本属性", "真理既是绝对真理，又是相对真理"], "a": 3, "e": ".【D】A项错误，在马克思唯物主义中，物质决定意识，意识是客观实在的反映，这是两个概念，无法等同；B项错误，是唯心主义的观点。不符合马克思主义的唯物主义；C项错误，运动是物质的根本属性与存在方式；D项正确，任何真理都具有绝对的一面，又有相对的一面，它们之间的关系是辩证统一的。因此正确答案为D。", "tag": "政治常识"},
{"id": "pol-120", "q": "马克思主义产生的阶级基础是：无产阶级和资产阶级的矛盾上升为社会的主要矛盾，无产阶级开始作为政治力量登上历史舞台。", "options": ["独立的", "分散的", "暂时依附于资产阶级的", "有组织的、团结的"], "a": 0, "e": ".【A】马克思主义产生的阶级基础：无产阶级的产生和发展（三大工人武装起义：法国里昂工人起义、英国宪章运动、德国西里西亚纺织工人起义，标志无产阶级已经作为一支独立的政治力量登上历史舞台）。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-121", "q": "“一条锁链，最脆弱的一环决定其强度；一只木桶，最短的一片决定其容量。”这段话主要强调：", "options": ["要坚持一切从实际出发", "要看到整体的统率和决定地位", "要重视局部对整体的制约作用", "要重视意识的能动作用"], "a": 2, "e": ".【C】C项正确：结合题干，锁链最脆弱的一环决定它的强度，木桶最短的一片决定它的容量，“最脆弱的一环”和“最短的一片”相对于“锁链”和“木桶”来说，是局部与整体的关系，主要强调局部对整体具有制约作用，需要引起重视。A项错误：“一切从实际出发”强调的是想问题、办事情要把客观存在的实际事物作为根本出发点，题干没有体现，排除。B项错误：题干强调的是局部对整体起制约作用，没有体现整体的统率和决定地位这一哲理，排除。D项错误：“意识的能动作用”指人的主观意识和实践活动对于客观世界的反作用或能动作用，题干没有体现“意识”，排除。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-122", "q": "传说大禹治水时，左手执“准绳”，右手拿“规矩”；“望山川之形，定高下之势”，“此数所由生也”。这个传说说明：", "options": ["认识是在变革对象的实践中发生的", "实践是认识发展的根本动力", "实践是社会性、历史性的活动", "认识的最终目的在于实践"], "a": 0, "e": ".【A】A项正确：此题考查对认识论的理解。大禹通过不断地观察山川河流走势，用“准绳”和“规矩”不断实践测量，最终发现勾股定理（“此数”指勾股定理）。体现出通过实践的不断变化才能正确认识事物和规律，说明认识是在变革对象的实践中发生的。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-123", "q": "语言是一种味道，人们依靠它传情达意；语言更是一面镜子，人们从中可以看到时代的身影，社会的不同阶段人们的问候语也会随之改变。这表明：", "options": ["社会意识是变化发展的", "社会意识对社会存在有反作用", "社会意识决定社会存在", "社会意识不具有相对独立性"], "a": 0, "e": ".【A】A项正确：社会意识指社会的精神生活过程，它是社会存在在社会精神领域中的反映。社会存在决定社会意识，社会意识是社会存在的反映，社会存在的性质和变化决定社会意识的性质和变化。题干中，语言属于社会意识的范畴，人们的问候语随着社会阶段的变化而变化，说明社会意识是变化发展的。B项错误：社会意识对社会存在有反作用，指不同性质的社会意识对社会存在起着不同性质的作用。题干中没有体现社会意识对社会存在所起的作用，排除。C项错误：“社会意识决定社会存在”本身表述错误，根据马克思历史唯物主义，应该是社会存在决定社会意识，排除。D项错误：“社会意识不具有相对独立性”本身表述错误，根据马克思历史唯物主义，社会意识具有相对的独立性，社会存在的变化最终会引起社会意识的相应变化，但是社会意识的变化与社会存在的变化并非一定同步进行，排除。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-124", "q": "党的思想路线的理论基础是：", "options": ["联系的观点", "马克思主义认识论", "对立统一规律", "唯物主义历史观"], "a": 1, "e": ".【B】A项错误，联系的观点是指事物内部各要素之间和事物之间相互影响、相互制约和相互作用的关系；B项正确，党的思想路线又称作“实事求是的思想路线”，实事求是思想路线在中国共产党的确立，是以马克思主义认识论为哲学基础的，是马克思主义认识论在马克思主义中国化实践过程中的运用、丰富和发展；C项错误，对立统一规律又称矛盾规律，矛盾是辩证法的核心概念；D项错误，唯物主义历史观解决的是社会存在与社会意识的关系问题。A、C、D项均不是党的思想路线的理论基础，排除。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-126", "q": "“满眼风光多闪烁，看山恰似走来迎；仔细看山山不动，是船行。”这一诗句包含的哲理是：", "options": ["时空的无限性和有限性的统一", "运动的绝对性和静止的相对性的统一", "物质运动的无限性和时空的有限性的统一", "物质运动的客观性和时空的主观性的统一"], "a": 1, "e": ".【B】B项正确，题干诗句出自敦煌曲子词《浣溪沙》，大意是站在船上看着两岸秀丽的风光，看见山好像山迎面走来。仔细看山山不动，原来是“我”的船在走。“看山恰似走来迎”、“船行”说的是绝对运动；“仔细看山山不动”，说的是相对静止。诗句反映的正是运动的绝对性和静止的相对性的统一；A、C、D三项错误，题干强调的是运动和静止的关系，跟时空、客观性和主观性无直接关系，A、C、D不选。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-127", "q": "下列说法中能体现唯物主义和唯心主义根本分歧的是：", "options": ["“生死有命富贵在天”与“物是观念的集合”", "“世异则事异，事异则备变”与“天不变，道亦不变”", "“气者，理之依也”与“理生万物”", "“不入虎穴、焉得虎子”与“秀才不出门，全知天下事”"], "a": 2, "e": ".【C】A项是客观唯心主义和主观唯心主义的对应，二者均为唯心主义范畴；B项是唯物主义发展观和形而上学静止观的对应，二者均为辩证法范畴；C项是朴素唯物主义与客观唯心主义的对应，前者主张物质第一性，后者支持意识第一性，体现了唯物主义与唯心主义的根本分歧；D项二者均涉及实践与认识的关系，同属于唯物主义观点。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-128", "q": "我们党和政府的宗旨是：", "options": ["加强和改进党的领导", "全心全意为人民服务", "全面建成小康社会", "建设中国特色社会主义"], "a": 1, "e": ".【B】《中国共产党章程》规定，全心全意为人民服务是中国共产党的根本宗旨。在我国，中国共产党成为执政党以后，所领导的政权是人民政权，政府是人民政府，全心全意为人民服务是政府工作根本宗旨。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-129", "q": "《三国演义》开篇称“天下大势，分久必合，合久必分”。但是这句话未必准确，因为：", "options": ["事物的发展需以条件为前提", "事物的本质不以时间为转移", "事物的质变是从量变开始的", "矛盾双方是可以相互转化的"], "a": 1, "e": ".【B】此题为争议题。若破题的重点落在“分”与“合”上：事物是不断变化发展的，“分”与“合”就是发展变化的一种体现。而题干说“分久必合、合久必分”不正确，原因就是这种变化发展不是无条件的，绝对的，而是需要有一定的条件才能可以，符合A项的表述。若破题重点落在“久”上：题干表述为时间久了事物本质就会发生变化，由“合”到“分”，由“分”到“合”。如果这种说法不正确，则说明时间长短不是事物本质变化的因素，符合B项的表述。C无关选项，D的说法说明题干正确，故都不选，答案在AB之间。再回到题干，“分久必合、合久必分”，强调“久”字的意味更浓一些，侧重点在时间对事物本质的影响上，故粉笔题库倾向性答案为B。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-130", "q": "古诗云：“王子去求仙，丹成入九天。洞中方七日，世上已千年。”这是用神话形式说明时间：", "options": ["是客观的", "是有限的", "是可知的", "是相对的"], "a": 3, "e": ".【D】“洞中方七日，世上已千年”中通过“七日”与“千年”的对比，说明的是时间的相对性。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-131", "q": "“从物到感觉和思想”与“从感觉和思想到物”是两条根本对立的认识路线，它属于：", "options": ["辩证法与形而上学的对立", "唯物主义反映论与唯心主义先验论的对立", "可知论与不可知论的对立", "辩证唯物主义与旧唯物主义的对立"], "a": 1, "e": ".【B】“从物到感觉和思想”的观点承认物质是第一性，意识是第二性，认识是主体对客体的反映，属于唯物主义反映论，“从感觉和思想到物”的观点把认识看作是先于物质、先于实践经验的东西，属于唯心主义先验论。故正确答案为B。本题相关知识点：唯物辩证法和形而上学的对立体现在是否承认矛盾，是否承认事物的内部矛盾是事物发展的源泉；可知论与不可知论的对立在于物质世界能否被人类感知；辩证唯物主义与旧唯物主义的区别在于旧唯物主义不承认社会实践对认识的决定作用，其反映论是机械的形而上学反映论，而辩证唯物主义承认实践对认识的决定作用，把辩证法跟认识论紧密结合在一起。", "tag": "政治常识"},
{"id": "pol-132", "q": "《老子》中说：“合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。”这句话蕴含的哲理是：", "options": ["事物的变化发展从量变开始，量变达到一定程度必然会引起质变", "质变是量变的前提和必要准备", "质变优于量变", "质变和量变相互渗透"], "a": 0, "e": ".【A】A项正确，老子这句话的意思是“合抱的大树，生长于细小的幼苗；九层的高台，筑起于每一堆泥土；千里的远行，是从脚下第一步开始走出来的”，这说明了事物的发展都有一个从小到大的过程，微小的事物积累到一定阶段，就能变成大的事物，这其中蕴含的哲理便是量变引起质变；B项错误，量变才是质变的前提和必要准备；C项错误，质变和量变是事物发展的两种状态，不能简单地肯定质变优于量变；D项错误，不是题干所蕴含的哲理。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-133", "q": "21 世纪以来，我国进入新一轮婚育高峰期，结婚人数以每年10%的比例增长，加之国民收入水平不断提高，婚庆服务产业得到空前发展。这表明：", "options": ["消费是生产的结果", "生产为消费创造动力", "消费是生产的动力", "生产决定消费对象"], "a": 2, "e": ".【C】本题考查消费与生产的辩证关系，即生产决定消费，消费对生产有重大的反作用。没有生产就没有消费，同时消费是生产的目的和动力。本题中，随着结婚人数增多，国民收入提高，婚庆活动的消费需求增加，从而促进了婚庆服务产业的发展，显然是消费带动生产。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-134", "q": "信念是人们在一定认识的基础上，对某种思想理论、学说和理想所抱的坚定不移的观念和真诚信服、坚决执行的态度。检验信念正确与否、科学与否的唯一标准是：", "options": ["理论推断", "社会实践", "主观愿望", "真诚信仰"], "a": 1, "e": ".【B】辩证唯物主义认识论认为，只有实践才能证明认识是否具有客观的真理性。信念也是一种主观认识，只有通过社会实践，才能检验信念是否正确、科学。A、C、D都属于主观认识，不能作为检验标准。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-135", "q": "有人根据玛雅太阳历提出“2012 世界末日”。科学界多年的观测与研究表明：2012 年可能大规模爆发太阳耀斑，会影响地球通讯系统，但不会导致地球文明毁灭。下列说法正确的是：", "options": ["“世界末日说”对当代科学研究具有指导意义", "“世界末日说”缺乏科学依据，不是对客观存在的反映", "“世界末日说”与太阳耀斑的内在关联，体现了联系的普遍性", "科学界对太阳耀斑的爆发及其后果的预测，反映了联系的客观性"], "a": 3, "e": ".【D】文段中两句话“末日”和“不会导致地球文明毁灭”表明，科学研究并没有印证玛雅人的预测。科学家的研究就是从不同事物的关联中去寻找规律，规律的存在即表明联系是客观的，是事物本身固有的，不以人的主观意志为转移。这种联系并不局限于自然界的事物之间，也存在于人类实践活动创造出来的社会生产活动的各个领域之间。A项错误，指导意义无从谈起；B项错误，任何意识形式，不论其内容如何特殊，不论其是否远离现实生活，都不是主观自生的，也不是从天而降的，都是来自客观世界，都能在客观世界中找到它的“原型”；C项错误，文中并没有指明这种内在关联。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-136", "q": "拥有私家车的人越来越多，我国正在迈向汽车社会，汽车社会的来临呼唤“汽车道德”的出现体现了：", "options": ["社会存在决定社会意识", "社会意识具有反作用", "世界是不断变化发展的", "社会意识具有相对独立性"], "a": 0, "e": ".【A】本题汽车社会的表现是“拥有私家车的人越来越多”，这是一种客观现象（社会存在），而“汽车道德”属于主观范畴（社会意识）。马克思主义认为，社会存在决定社会意识，社会意识是社会存在的反映，社会存在的性质和变化决定社会意识的性质和变化。这也就是本题所说的汽车社会需要“汽车道德”。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-137", "q": "十八大报告指出，建设中国特色社会主义总体在布局经济建设、政治建设、文化建设、社会建设、生态文明建设五位一体，这是中国特色社会主义事业总体布局的进一步完善，在社会主义现代文化建设的总体中，逐步达到社会和谐必须坚持：", "options": ["全面的观点", "能动的观点", "实践的观点", "前途光明的观点"], "a": 0, "e": ".【A】根据题干可知，十八大强调了中国特色社会主义建设是包括经济建设、政治建设、文化建设、社会建设、生态文明建设五位一体建设的重要性，体现了全面的观点，这五个建设协调发展，才能达到社会的和谐。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-138", "q": "当前拥有私家车的人越来越多，我国正在迈向汽车社会，汽车社会的来临呼唤“汽车道德”——如自觉遵守交通规则、不闯红灯、不酒驾等。从唯物史观看“汽车道德”的出现体现了：", "options": ["世界是不断变化发展的", "社会意识具有反作用", "社会存在决定社会意识", "社会意识具有相对独立性"], "a": 2, "e": ".【C】历史唯物主义认为，社会存在是社会意识的前提和基础。有什么样的社会，就会有什么样的社会意识与之相适应。社会存在决定社会意识的内容和形式。本题中，随着私家车数量的增加，我国逐渐形成“汽车社会”，有了“汽车社会”，人们开始呼唤“汽车道德”来规范“汽车社会”，这正是社会存在决定社会意识的体现。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-139", "q": "人生在平淡中寻找幸福，在细微中品味幸福，在孤独中守望幸福，在遗忘中怀念幸福。幸福的生活需要哲学的指引，这是因为：", "options": ["哲学可以解决一切问题", "哲学是哲学家对自己实践活动的总结", "哲学为人们生活提供有益的指导", "真正的哲学就是生活本身"], "a": 2, "e": ".【C】本题可以采用排除法来作答。A项错误，错在说法过于绝对，回顾个人经历，可知生活中很多问题无法通过哲学来解决，更不用说一切问题了；B项错误，就哲学本身的定义而言，哲学是一种社会意识形态，是理论化的、系统化的世界观。哲学家根据自身的实践和观察提出某种哲学学说，但这并不完全等同于哲学；C项正确；D项错误，哲学来源于生活，但高于生活。正是因为哲学高于生活，能够为人们的生活提供有益的指导，所以幸福的生活需要有哲学的指引。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-140", "q": "“你最痛苦的时候，窗外有小鸟在快乐地歌唱”，这句格言的寓意是：", "options": ["学习小鸟快乐生活", "世界的本质是客观的", "人的尊严在于思想", "思维是客观存在的反映"], "a": 1, "e": ".【B】本题说明人的主观痛苦与外在的环境无关。人的痛苦和小鸟的快乐都是独立存在的社会物质，这强调了世界的本质是客观的，不以人的意识为转移。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-141", "q": "有人依据玛雅太阳历提出“2012 世界末日说”。科学界多年的观测和研究表明：2012 年可能大规模爆发太阳耀斑，会影响地球通讯系统，但不会导致地球文明毁灭。下面说法正确的是：", "options": ["“世界末日说”对当代科学研究具有指导意义", "“世界末日说”缺乏科学依据，不是对客观存在的反映", "“世界末日说”与太阳耀斑爆发的内在联系，体现了联系的普遍性", "科学界对太阳耀斑的爆发及其后果的预测，反映了联系的客观性"], "a": 3, "e": ".【D】A项错误，依据玛雅太阳历提出的“世界末日说”本身并不科学，因而不能指导科学研究；B项错误，“世界末日说”尽管不是科学的理论，但仍然是对客观存在的反映，只不过是错误的反映；C项错误，“世界末日说”与太阳耀斑爆发并不存在内在联系，这种说法本身是错误的。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-142", "q": "近年来，“瘦肉精”、“地沟油”等食品安全恶性事件不断发生，食品安全防线的失守告诉我们，光是整治企业，问题并不能得到根本解决，在监管方面，还有大量的难题需要攻关。这表明：", "options": ["内因要通过外因起作用", "外因在事物发展中起决定性作用", "内因是事物发展的条件", "事物的发展是内外因共同作用的结果"], "a": 3, "e": ".【D】本题通过对社会热点现象的描述考查哲学基本原理。唯物辩证法认为事物的内部矛盾（内因）是事物自身运动的源泉和动力，是事物发展的根本原因。外部矛盾（外因）是事物发展、变化的第二位的原因。内因是变化的根据，外因是变化的条件，外因通过内因而起作用。内因、外因共同影响事物的发展。企业诚信缺失是内因，监管方面不足是外因，食品安全防线失守是这两因素共同造成的结果。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-143", "q": "“从一个较长的历史时期来说，改革会使人人受益”，但“改革不是一首田园诗，它伴随着眼泪和痛苦”。对这两句话包含的哲学道理理解正确的是：", "options": ["量变是质变的前提和必要准备，质变是量变的必然结果", "事物的发展是前进性和曲折性的统一", "矛盾的主要方面决定事物的性质", "矛盾双方在一定条件下相互转化"], "a": 1, "e": ".【B】改革从一个较长的历史时期来说会使人受益，这说明事物发展的总趋势是前进的，改革过程中也伴随着“眼泪和痛苦”说明了事物发展的曲折性。题干中的两句话揭示了事物的发展是前进性和曲折性的统一。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-144", "q": "马克思主义哲学认为，认识一旦形成，就会反作用于实践，指导实践的全过程。这是因为：①实践是检验认识正确与否的唯一标准②实践目标的确立，需要认识的指导③对实践手段、方法、道路、步骤的取舍，需要认识的指导④对实践结果的评价，需要认识的指导⑤认识在不断发展过程中，需要实践提供动力", "options": ["①③⑤", "②③④", "①②③⑤", "②③④⑤"], "a": 1, "e": ".【B】本题可以用排除法得到答案。第⑤“认识在不断发展过程中，需要实践提供动力”表达的是实践对认识的作用，而没有体现出认识对实践的指导。A、C、D选项中皆有⑤，予以排除，只有B项是正确答案。故正确答案为B。本题相关知识点：马克思主义哲学认为，认识活动及其成果具有相对独立性，遵循其特有的活动方式和发展规律，它一经形成，便能反作用于实践，这种指导作用表现在许多方面：认识可以使主体了解、把握主体和客体及其相互作用的规律性，指导主体自觉地按照客观规律去从事改造世界的活动；认识可以使主体在实践活动前，既确定符合自身需要，又符合客观实际的目标、方案、步骤和措施，对实践活动作出预测和规划；认识可以指导主体将局部经验上升为理论；认识还可以使主体实现对自身的认识，并自觉调整自己的活动，以适应改造客观的需要。所以，我们认为，首先理论是对事物本质和规律的认识，它可以而且应该走在实践的前头，指导实践活动的进程；其次，科学理论能预见未来，指明实践的方向。", "tag": "政治常识"},
{"id": "pol-145", "q": "“天下虽安，忘战必危”是我国古代著名的军事思想，充满着朴素的辩证法智慧。下列体现的哲学思想与这句话相同的是：", "options": ["“有心栽花花不开，无心插柳柳成荫”", "“不谋全局者，不足以谋一域”", "“旱则资舟，水则资车，以待乏也”", "“富贵而恣势弄权，乃自取灭亡之道”"], "a": 2, "e": ".【C】题干的“天下虽安，忘战必危”体现了矛盾双方在一定条件下会相互转化，安会转化为危，要增强预见性。C项旱、舟之间，水、车之间也体现出矛盾的相互转化，在干旱的时候储备好船，雨水多的时候就会有用处。故正确答案为C。", "tag": "政治常识"},
{"id": "pol-146", "q": "下列选项中三国典故与哲学论断对应错误的是：", "options": ["士别三日，当刮目相看——用发展的眼光看问题", "草船借箭——人可以认识并利用规律", "张飞醉酒失徐州，借酒破张郃——矛盾是对立统一的", "望梅止渴——理性认识依赖于感性认识"], "a": 3, "e": ".【D】本题考查哲学常识。A项对应正确，“士别三日”出自《三国志》，意思是指人离开后不久。全句“士别三日，当刮目相看”表达别人已有进步，应当用发展的眼光看待别人的意思。B项对应正确，草船借箭、庖丁解牛、预测彗星的回归、把卫星送入预定轨道等，这些都是利用对规律的认识，预见事物发展的趋势和方向，从而有效地指导实践活动，取得预期目的的典型事例。C项对应正确，同样是饮酒，利用不当可致“战败弃城”，利用得当则可“战胜得利”，体现了事物之间或事物内部诸要素之间既对立又统一的关系，对立和统一是矛盾的两个根本属性。D项对应错误，望梅止渴出自《世说新语假谲》，“曹操行军途中，失去了有水源的道路，士兵们都很渴，于是他传令道：‘前边有一片梅子林，结了许多梅子，又酸又甜，可以解除我们的口渴。’士兵听后，嘴里都流出了口水。曹操利用这个机会把士兵们带领到前方有水源的地方”。所以“望梅止渴”体现的是意识的能动作用，而非选项中所说的理性认识依赖于感性认识。本题为选非题，故正确答案为D。", "tag": "政治常识"},
{"id": "pol-147", "q": "关于19 世纪下半叶至20 世纪初的“唯意志论”，下列说法不正确的是：", "options": ["代表人物是叔本华和尼采", "主要观点是“意志是宇宙的本体”", "先于马克思主义哲学产生", "受印度哲学和佛学影响较大"], "a": 2, "e": ".【C】以叔本华和尼采为代表的唯意志论，特别是其非理性主义倾向，对19世纪末20世纪初流行于德、法等国的生命哲学和历史哲学的发展有很大的影响。叔本华研究过印度哲学，受印度佛学影响较大，认为科学和哲学在意志领域达到了极限，只有依靠神秘的洞察力才能领悟到意志的本性。马克思哲学产生于19世纪40年代，早于“唯意志论”。本题为选非题，故正确答案为C。", "tag": "政治常识"},
{"id": "pol-148", "q": "按照唯物辩证法原理，以下说法错误的是：", "options": ["运动的主体是物质", "思维是人脑的存在形式", "运动就是物质的存在形式", "静止是一种特殊的运动形式"], "a": 1, "e": ".【B】B项错误，“思维是人脑的存在形式”是唯心主义观点，是意识决定物质的观点。本题为选非题，故正确答案为B。本题相关知识点：意识在本质上是物质在人脑中的主观映象。意识是物质的产物，但不是物质本身。从物质器官看，意识是特殊的物质——人脑的机能。人脑是产生意识的物质载体，人脑也是物质，所以说物质是意识产生的主体。同样，运动是物质的运动，物质是运动的主体。世界上没有离开物质的运动，运动必然有它的物质主体，从简单的机械运动到复杂的社会运动和思维运动，都离不开物质主体。总之，各种运动形式的承担者都是物质，世界上不存在没有物质的运动。任何领域中的任何形式的运动，都以物质为其现实基础。设想无物质的运动，必然陷入唯心主义。", "tag": "政治常识"},
{"id": "pol-149", "q": "哲学的基本问题，即思维与存在的关系问题，是指：", "options": ["物质与意识谁具有决定性", "物质与意识是否具有互换性", "物质与意识是否具有同一性", "物质与意识是否具有相似性"], "a": 0, "e": ".【A】意识和物质、精神与自然界，究竟谁是世界的本原，即物质与意识谁是第一性，谁是第二性的问题是哲学的基本问题。故正确答案为A。", "tag": "政治常识"},
{"id": "pol-150", "q": "从古代的“把酒问青天”、“嫦娥奔月”，到今天的“神舟”号系列对太空的探索，再到“天宫一号”的发射，我们对太空的了解越来越深入，这说明：①追求真理是一个永无止境的过程②人类对自然界的认识是一帆风顺的③实践锻炼并提高了人的认识能力④实践决定认识，认识是实践的目的", "options": ["①②", "①③", "②④", "③④"], "a": 1, "e": ".【B】实践是认识的来源，随着实践活动的不断深入，认识也会不断加深，认识反过来进一步指导实践，实践是认识的来源，也是认识的最终目的。所以“追求真理是一个永无止境的过程”，“实践锻炼并提高了人的认识能力”的说法是正确的；“实践决定认识，认识是实践的目的”的说法错误，应为“实践决定认识，实践是认识的目的”；人类对自然界的认识并不是一帆风顺的，受技术手段制约，也经历了曲折的过程，所以“人类对自然界的认识是一帆风顺的”说法不正确。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-151", "q": "从社会总成本角度，分析社会资本再生产问题的核心是：", "options": ["社会总成本的结构", "社会总成本的补偿", "社会总成本的支出", "社会总成本的收入"], "a": 1, "e": ".【B】从社会总成本角度来分析，社会资本再生产问题的核心问题是社会总产品的实现问题，而只有社会总产品中的各个部分都能在价值上和物质上得到补偿，社会产品才能顺利得到实现，所以社会资本再生产问题的核心是社会总成本的补偿。故正确答案为B。本题相关知识点：社会总产品的价值补偿，是指社会总产品各个组成部分的价值，如何通过全部商品的出售，以货币形式收回，用以补偿生产中预付的不变资本和可变资本的价值，并获得剩余价值。社会总产品的物质补偿，是指社会总产品的各个组成部分的价值转化为货币以后，如何再转化为所需要的产品，以补偿社会生产中消耗的生产资料和生活资料。", "tag": "政治常识"},
{"id": "pol-152", "q": "荀子说：“不闻不若闻之，闻之不若见之，见之不若知之，知之不若行之。学至于行而止矣。明之，行也。”这段话的哲学寓意是（）。", "options": ["事物的部分离不开整体", "实践是认识的来源和目的", "矛盾双方在一定条件下可以相互转化", "事物发展是前进性和曲折性的统一"], "a": 1, "e": ".【B】本题考查政治常识。题干意思是在学习中听说比不听好，见到比听说好，知晓比见到好，实践比知晓好，学习的最终就是实践，实践了，就明白了。A项错误，整体和部分不可分割，整体是由部分构成的，部分是整体的部分，本题没有体现这点。B项正确，本题强调了实践是认识的来源和目的，要重视实践。C项错误，本题没有体现矛盾双方在一定的条件下可以相互转化。D项错误，本题没有体现事物发展是前进性和曲折性的统一，体现了实践是认识的来源和目的。故正确答案为B。", "tag": "政治常识"},
{"id": "pol-153", "q": "《习近平谈治国理政》中有精彩语录“要紧紧牵住核心技术自主创新这个‘牛鼻子’”和“我国网信领域广大企业家、专家学者、科技人员要树立这个雄心壮志，要争这口气，努力尽快在核心技术上取得新的重大突破”。以上论述阐述的哲学道理是（）。", "options": ["要看到矛盾的主要方面", "发展的实质是新事物必然取代旧事物", "事物的发展是前进的、上升的运动", "要抓住事物的主要矛盾"], "a": 3, "e": ".【D】本题考查政治常识。A项错误，矛盾的主要方面是指在单个矛盾中，在矛盾的双方之中，处于支配地位并起着主导作用的一方，矛盾的主要方面决定事物的性质。题干中没有体现“矛盾的主要方面”。B项错误，发展的实质是新事物的产生和旧事物的灭亡。题干中没有体现出“新事物”与“旧事物”的更替。C项错误，事物的发展是前进的、上升的运动。题干中没有体现出事物发展变化的趋势是前进的、上升的。D项正确，要紧紧牵住自主创新这个“牛鼻子”，体现出掌握核心技术的主要矛盾、关键部分就是“自主创新”，我们要善于抓主要矛盾，在核心技术上取得新的重大突破。故正确答案为D。", "tag": "政治常识"},
{"id": "pol-155", "q": "有经验的船长在遇到风暴时,不是将船中的东西扔到海里,而是将船舱装入一定量的水,以此来抵御风暴,体现的哲理是（）。", "options": ["事物是普遍联系的", "矛盾双方可以相互转化", "量变会引起质变", "矛盾的普遍性寓于特殊性之中"], "a": 1, "e": ".【B】本题考查政治常识。A项错误，联系是普遍的，世界上一切事物都与周围其他事物有着这样或那样的联系，世界是一个普遍联系的有机整体，但题干并未体现该观点。B项正确，风暴来临时船舱进水本来是非常危险的，但是船长通过装入一定量的水来提高载重，反而成功抵御风暴，将危机转化为优势，体现的是矛盾双方可以互相转化。C项错误，量变是质变的必要前提，量变到一定程度会引起质变，但是题干并未体现这一观点。D项错误，矛盾的普遍性需要通过具体矛盾表现出来，即共性寓于个性之中，但是本题并未体现共性与个性关系。故正确答案为B。", "tag": "政治常识"}
);
